INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('3cb65471-1fc1-4055-9cfa-63d7514aeaee'::uuid, 'card_description', 'Temples to the moon god Sin and the sun god Shamash were built and dedicated through the 15th century BC.', 'On a south facing spur by the Tigris, Aššur held the palace and temples of Ashur, Sin, Shamash and Ishtar, a city lived in for approximately 3,000 years before it was sacked.', 'teaser-card-s008:3cb65471-1fc1-4055-9cfa-63d7514aeaee:card_description', 'teaser-card-s008 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'a56a1d1d9d0a6f761f647f53c415225948530aca5c354b9542bda61276a34058|aa07ef9b51d7a527fbd8c08b426b05d417f450c95bab4a6dce5e83403e2282b9|aa07ef9b51d7a527fbd8c08b426b05d417f450c95bab4a6dce5e83403e2282b9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a south facing spur by the Tigris, Aššur held the palace and temples of Ashur, Sin, Shamash and Ishtar, a city lived in for approximately 3,000 years before it was sacked."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "on a south facing spur [S4]; by the Tigris [S2]; held the palace and temples of Ashur, Sin, Shamash and Ishtar [S5]; lived in approximately 3,000 years [S3]; before it was sacked [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Aššur is an ancient city (a settlement, capital of the Assyrian Empire) on the Tigris in Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Assur]; The city lies on a south facing spur by the Tigris [SUPPORTED: https://en.wikipedia.org/wiki/Assur]; The city held the palace and temples of Ashur, Sin, Shamash and Ishtar [SUPPORTED: https://en.wikipedia.org/wiki/Assur]; The city was lived in for approximately 3,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Assur]; The city was sacked (by the Sasanian Empire in the mid-3rd century AD), and the 3,000 years of occupation ran up to that sack [SUPPORTED: https://en.wikipedia.org/wiki/Assur]"}]'::jsonb),
    ('3dbbef3c-4605-4a1f-b04f-cadd63462673'::uuid, 'card_description', 'Founded around 3800 BC, this Sumerian city reached its height under the Third Dynasty of Ur. Its Royal Tombs held gold, lapis lazuli, and mass ritual burials of royal attendants.', 'Over Ur rise the partially restored ruins of its Ziggurat, which held the shrine of Nanna. In 1928 the old city gave up the Lyres of Ur, harp-like instruments shaped like a bull.', 'teaser-card-s008:3dbbef3c-4605-4a1f-b04f-cadd63462673:card_description', 'teaser-card-s008 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'c56fdb4976f9915bd1eca6df98af6cd4a0fc57d9cc18c14951c72c024603d84e|065ed5c4026ed9a38df07802c89c96a48645bc0366ad5f22fb61279925753d02|065ed5c4026ed9a38df07802c89c96a48645bc0366ad5f22fb61279925753d02', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Over Ur rise the partially restored ruins of its Ziggurat, which held the shrine of Nanna. In 1928 the old city gave up the Lyres of Ur, harp-like instruments shaped like a bull."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "partially restored ruins of the Ziggurat [S3]; ziggurat held the shrine of Nanna [S3]; in 1928 excavation of the old city revealed the Lyres of Ur [S5]; harp-like instruments shaped like a bull [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ur is an ancient city (Sumerian city-state) in Iraq, with the Ziggurat of Ur as its landmark [SUPPORTED: https://en.wikipedia.org/wiki/Ur]; The ruins of the Ziggurat of Ur are partially restored [SUPPORTED: https://en.wikipedia.org/wiki/Ur]; The Ziggurat held the shrine of Nanna [SUPPORTED: https://en.wikipedia.org/wiki/Ziggurat_of_Ur]; The Lyres of Ur came from the old city of Ur (the Royal Cemetery at Ur) [SUPPORTED: https://en.wikipedia.org/wiki/Lyres_of_Ur]; The Lyres of Ur are harp-like instruments shaped like a bull [SUPPORTED: https://en.wikipedia.org/wiki/Ur]; The old city gave up the Lyres of Ur in 1928 (the year is not settled: the Wikipedia article Ur says 1928, the article Lyres of Ur says ''In 1929, archaeologists led by the British archaeologist Leonard Woolley ... found the instruments'', and the Penn Museum places the discovery of the silver and the bull-headed gold lyre in the Great Death Pit in the ''1928-29 season'') [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('3dbd5144-7f81-4aca-a88b-527f1928b0f3'::uuid, 'card_description', 'A 4th–3rd century BC Saka burial mound, 6 m high and 60 m around, yielded a silver cup with an undeciphered inscription. The script links this steppe kurgan to Central Asian writing traditions.', 'Discovered in 1969, the Issyk Kurgan held a skeleton, warrior''s equipment and 4,000 gold ornaments, and a silver cup bearing an inscription now known as the Issyk inscription.', 'teaser-card-s008:3dbd5144-7f81-4aca-a88b-527f1928b0f3:card_description', 'teaser-card-s008 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '3cd16ccd0f681acbabaa6e2c577bbba98fae5b42cc1b7bb6b7904a562d9f6564|711f5e3e61d7c000e529b7c2548c205a74ec55af14ee1970d8123ed1d958720a|711f5e3e61d7c000e529b7c2548c205a74ec55af14ee1970d8123ed1d958720a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Discovered in 1969, the Issyk Kurgan held a skeleton, warrior''s equipment and 4,000 gold ornaments, and a silver cup bearing an inscription now known as the Issyk inscription."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "discovered in 1969 [S1]; held a skeleton, warrior''s equipment [S6]; 4,000 gold ornaments [S6]; silver cup bearing an inscription [S2]; known as the Issyk inscription [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Issyk Kurgan is a burial mound (kurgan) in Kazakhstan, near Issyk [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]; The Issyk Kurgan was discovered in 1969 [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]; The kurgan held a skeleton [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]; The kurgan held warrior''s equipment [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]; The kurgan held 4,000 gold ornaments [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]; The kurgan held a silver cup bearing an inscription, now known as the Issyk inscription [SUPPORTED: https://en.wikipedia.org/wiki/Issyk_kurgan]"}]'::jsonb),
    ('3dde8dfa-0538-4c2e-9236-1dcb5e24693a'::uuid, 'card_description', 'Built in phases from the 2nd to 5th century AD. A fresco portrait of a woman — possibly the mistress of the house — survives. One reconstructed wing still stands at Butser Ancient Farm.', 'By 200 AD Sparsholt Roman Villa had an aisled house. In the early 4th century a winged-corridor house rose at right angles to it, and both gained tessellated pavements and mosaics.', 'teaser-card-s008:3dde8dfa-0538-4c2e-9236-1dcb5e24693a:card_description', 'teaser-card-s008 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '4c04934a7d22bd120d00ba5b06f7e4efd53522d259e459ca17995232b2c99274|9984cd45f88884090b2e70c2fb65fd812bba93a044bfc8e83ce1dce25e462586|9984cd45f88884090b2e70c2fb65fd812bba93a044bfc8e83ce1dce25e462586', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "By 200 AD Sparsholt Roman Villa had an aisled house. In the early 4th century a winged-corridor house rose at right angles to it, and both gained tessellated pavements and mosaics."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "by 200 AD the villa had an aisled house [S5]; in the early 4th century a winged-corridor house was built [S6]; the winged-corridor house was at right angles to the aisled house [S6]; both houses gained tessellated pavements and mosaics [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sparsholt Roman Villa was a Roman villa near Sparsholt, Hampshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Sparsholt_Roman_Villa]; By 200 AD the villa had an aisled house [SUPPORTED: https://en.wikipedia.org/wiki/Sparsholt_Roman_Villa]; In the early 4th century a winged-corridor house rose at right angles to the aisled house [SUPPORTED: https://en.wikipedia.org/wiki/Sparsholt_Roman_Villa]; Both houses gained tessellated pavements and mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Sparsholt_Roman_Villa]"}]'::jsonb),
    ('3e0423c9-947d-4a45-bf5f-8bd857e8e9cf'::uuid, 'card_description', 'A 114-117 AD triumphal arch with some of the best-preserved relief sculptures in the Roman world. The carvings show Trajan feeding orphans, building roads, and waging war.', 'Where the Via Appia enters Benevento stands the Arch of Trajan, built between 114 and 117 of limestone clad in Parian marble, later set into the city walls as the Porta Aurea.', 'teaser-card-s008:3e0423c9-947d-4a45-bf5f-8bd857e8e9cf:card_description', 'teaser-card-s008 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '8fa4e3a46061303d3fac051aa80fdb11d264d8b07501cd81a27f646de814baf7|687360631f4966e4f3a269495ebdb4e3df5e744b68cbdbd68e40465b3c27d733|687360631f4966e4f3a269495ebdb4e3df5e744b68cbdbd68e40465b3c27d733', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Where the Via Appia enters Benevento stands the Arch of Trajan, built between 114 and 117 of limestone clad in Parian marble, later set into the city walls as the Porta Aurea."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "stands where the Via Appia enters Benevento [S1, S2]; built between 114 and 117 [S3]; limestone [S8]; clad in Parian marble [S8]; later set into the city walls [S4]; known as Porta Aurea [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Arch of Trajan is an ancient Roman triumphal arch in Benevento, southern Italy [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Trajan_(Benevento)]; The arch stands across the Via Appia where it enters Benevento [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Trajan_(Benevento)]; The arch was built between 114 and 117 [SUPPORTED: https://cultura.regione.campania.it/en/web/itinerari/poi?id=399967&idItinerario=399941]; The arch is built of limestone [SUPPORTED: https://www.italia.it/en/campania/benevento/the-arch-of-trajan]; The limestone is clad in Parian marble [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Trajan_(Benevento)]; The arch was later set into (incorporated in) the city walls of Benevento [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Trajan_(Benevento)]; As part of the city walls the arch was known as the Porta Aurea [SUPPORTED: https://cultura.regione.campania.it/en/web/itinerari/poi?id=399967&idItinerario=399941]"}]'::jsonb),
    ('3fbcee0b-5778-4897-ba4a-9b792fd5305d'::uuid, 'card_description', 'A 6th-century BC temple to Apollo Zoster with a unique floor of large rectangular slabs. A later wall separated the inner sanctuary from the main chamber.', 'Children from the Vouliagmeni orphanage, at play on what is now Astir Beach, uncovered the ruins of the Temple of Apollo Zoster, founded in the sixth century BC, with a sekos and an adyton.', 'teaser-card-s008:3fbcee0b-5778-4897-ba4a-9b792fd5305d:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '14917987f689184bc94d47da80efd282947fe9a2656a05d06af5a8e09749f81a|29628576bd720e8d06889fab952343fce446150374ce221bb26209f96315f9c8|29628576bd720e8d06889fab952343fce446150374ce221bb26209f96315f9c8', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Children from the Vouliagmeni orphanage, at play on what is now Astir Beach, uncovered the ruins of the Temple of Apollo Zoster, founded in the sixth century BC, with a sekos and an adyton."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Children from the Vouliagmeni orphanage uncovered the ruins [S2]; they were playing on what is now Astir Beach [S2]; the site is the Temple of Apollo Zoster [S1, S3]; founded in the sixth century BC [S6]; it has a sekos and an adyton [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Apollo Zoster is an ancient Greek temple whose remains are at Vouliagmeni in Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The ruins are those of the Temple of Apollo Zoster (identified by inscriptions) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The temple was uncovered by children from the Vouliagmeni orphanage [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The children were playing on what is now Astir Beach when they uncovered it [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The temple was founded in the sixth century BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The temple has a sekos [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]; The temple has an adyton [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_Zoster]"}]'::jsonb),
    ('40229d13-d7b7-4b8f-acb3-7ae19fb085ba'::uuid, 'card_description', 'Agios Vasileios is the site of a Mycenaean palace, located 4 kilometers east of the village of Xirokambi in Laconia.', 'Some 10 km south of Sparta, a Mycenaean palace once commanded the plain west of the Eurotas River: Agios Vasileios, grown to about 20 hectares before destruction and abandonment.', 'teaser-card-s008:40229d13-d7b7-4b8f-acb3-7ae19fb085ba:card_description', 'teaser-card-s008 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'f7c9bcafa718e2999f5fd657886f0de12b6c7f1085c2a299b04053a68c321638|1eef35ddf3d8664146dbb16231421e68dc94d34f2e12ca15fdd41d630c841635|1eef35ddf3d8664146dbb16231421e68dc94d34f2e12ca15fdd41d630c841635', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Some 10 km south of Sparta, a Mycenaean palace once commanded the plain west of the Eurotas River: Agios Vasileios, grown to about 20 hectares before destruction and abandonment."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "some 10 km south of Sparta [S2]; a Mycenaean palace [S1]; it commanded the plain west of the Eurotas River [S2]; it grew to about 20 hectares [S5]; it faced destruction and abandonment [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Agios Vasileios in Laconia is the site of a Mycenaean palace [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The palace lay west of the Eurotas River [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The palace commanded the plain [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The site is some 10 km south of Sparta [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The site grew to a maximum size of about 20 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The palace was destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]; The palace site was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Agios_Vasileios,_Laconia]"}]'::jsonb),
    ('417445b4-e0db-49ac-99db-fe236794e9ff'::uuid, 'card_description', 'The cella of the Parthenon housed the chryselephantine statue of Athena Parthenos sculpted by Phidias and dedicated in 439 or 438 BC.', 'Begun in 447 BC, the Parthenon housed the chryselephantine Athena Parthenos of Phidias. In 1687 a Venetian bomb fell on it while the Ottomans used it as a munitions dump.', 'teaser-card-s008:417445b4-e0db-49ac-99db-fe236794e9ff:card_description', 'teaser-card-s008 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', 'a58a22d01934017270ce2d552e7792d964d0f7287843d4f37d50b25c66c15546|2c1c7bf830a4cc29f2abcc573c4fef7c8a5d3992564ace9d01840d381bfb40b4|2c1c7bf830a4cc29f2abcc573c4fef7c8a5d3992564ace9d01840d381bfb40b4', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Begun in 447 BC, the Parthenon housed the chryselephantine Athena Parthenos of Phidias. In 1687 a Venetian bomb fell on it while the Ottomans used it as a munitions dump."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "construction began in 447 BC [S3]; the Parthenon housed the chryselephantine Athena Parthenos [S8]; the statue is by Phidias [S8]; in 1687 a Venetian bomb fell on it [S4]; the Ottomans used it as a munitions dump [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Parthenon is a Greek temple [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]; The Parthenon stands on the Athenian Acropolis, Greece, dedicated to Athena [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]; Construction of the Parthenon began in 447 BC [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]; The Parthenon housed the chryselephantine Athena Parthenos by Phidias [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]; In 1687 a Venetian bomb fell on the Parthenon [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]; The Ottomans used the Parthenon as a munitions dump (gunpowder magazine) [SUPPORTED: https://en.wikipedia.org/wiki/Parthenon]"}]'::jsonb),
    ('43486bc0-4ffa-4420-ba63-482ebf306e8b'::uuid, 'card_description', 'A Greco-Buddhist site where 23,000 sculptures blending Greek and Buddhist art were excavated. Civil war destroyed nearly all of it — one of archaeology''s greatest losses.', 'At Hadda, some 23,000 Greco-Buddhist sculptures of clay and plaster were excavated. In one group from Tapa Shotor, the Buddha is surrounded by Herakles and Tyche holding a cornucopia.', 'teaser-card-s008:43486bc0-4ffa-4420-ba63-482ebf306e8b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'bfc648b422a115f03b723cdbbfdd364eb9121dbba7cdbddf9937dc0aa69b4a7f|3e38e578a541d38a5d3d9b220ffeb5a8aa6c28d41f7bdf30d8d849453de7f141|3e38e578a541d38a5d3d9b220ffeb5a8aa6c28d41f7bdf30d8d849453de7f141', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Hadda, some 23,000 Greco-Buddhist sculptures of clay and plaster were excavated. In one group from Tapa Shotor, the Buddha is surrounded by Herakles and Tyche holding a cornucopia."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "some 23,000 Greco-Buddhist sculptures were excavated at Hadda [S2]; the sculptures are of clay and plaster [S2]; a group from Tapa Shotor shows the Buddha surrounded by Herakles and Tyche [S6]; Tyche holds a cornucopia [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hadda is a Greco-Buddhist archaeological site south of Jalalabad in Nangarhar Province, Afghanistan [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]; Some 23,000 Greco-Buddhist sculptures were excavated at Hadda [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]; The sculptures are of clay and plaster [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]; Tapa Shotor is a site at Hadda [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]; A sculptural group from Tapa Shotor shows the Buddha surrounded by Herakles [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]; The same group shows Tyche holding a cornucopia [SUPPORTED: https://en.wikipedia.org/wiki/Hadda,_Afghanistan]"}]'::jsonb),
    ('44996991-ef99-4593-a645-74bf63d9056a'::uuid, 'card_description', 'An ancient wall stretching 4 km across the island of Fetlar, dividing it into two nearly equal halves. Its exact date and purpose remain unknown.', 'Funzie Girt, the Finns'' dyke, once ran for over 4 kilometres across the Shetland island of Fetlar, dividing it in two almost equal sections. What it was first built for is not known.', 'teaser-card-s008:44996991-ef99-4593-a645-74bf63d9056a:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '7c8121d6021671dee9fb94bc9dea577ccbb7bc6898ec5b8bf931ce0d4d0d0ad1|d5efde7bdd18b69f863aad48bbe66cbf0b59798e40f6005630b54ea1d5130a7a|d5efde7bdd18b69f863aad48bbe66cbf0b59798e40f6005630b54ea1d5130a7a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Funzie Girt, the Finns'' dyke, once ran for over 4 kilometres across the Shetland island of Fetlar, dividing it in two almost equal sections. What it was first built for is not known."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Funzie Girt is the Finns'' dyke [S3, S5]; it once ran for over 4 kilometres [S2]; it crossed the Shetland island of Fetlar [S1]; it divided the island in two almost equal sections [S2]; what it was first built for is not known [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Funzie Girt is an ancient wall (dyke) across the island of Fetlar in Shetland, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Funzie_Girt]; The name Funzie Girt means Finns'' dyke [SUPPORTED: https://en.wikipedia.org/wiki/Funzie_Girt]; The wall ran for over 4 kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Funzie_Girt]; The wall once divided the island in two almost equal sections [SUPPORTED: https://en.wikipedia.org/wiki/Funzie_Girt]; What the dyke was first built for (its original purpose) is not known [SUPPORTED: https://en.wikipedia.org/wiki/Funzie_Girt]"}]'::jsonb),
    ('452d8602-3ae3-4386-bfed-e1b3776dd298'::uuid, 'card_description', 'Two standing stones near the Hurlers stone circles, each about 2 m high. Legend says they were men turned to stone for playing music on the Sabbath.', 'On Bodmin Moor stand The Pipers, two stones approximately 2 metres high. Folklore makes them musicians, playing for three circles of dancers turned to stone for revelling on a holy day.', 'teaser-card-s008:452d8602-3ae3-4386-bfed-e1b3776dd298:card_description', 'teaser-card-s008 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '918d672b82afec4b8f4707b25ca5aac0d69e3879ab435ea15c6172c4e4585b46|003d904a98ac19a4ba88ec2d040490c8d7047d6e5b2cb4ee29005b06cfea9efd|003d904a98ac19a4ba88ec2d040490c8d7047d6e5b2cb4ee29005b06cfea9efd', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Bodmin Moor stand The Pipers, two stones approximately 2 metres high. Folklore makes them musicians, playing for three circles of dancers turned to stone for revelling on a holy day."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Pipers stand on Bodmin Moor [S1]; two stones [S1]; approximately 2 metres high [S2]; folklore makes them musicians [S4]; they play for three circles of dancers turned to stone [S4]; the dancers were turned to stone for revelling on a holy day [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Pipers are a standing-stone monument (a pair of standing stones) on Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]; The Pipers consist of two stones [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]; The stones are approximately 2 metres high [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]; Folklore makes the two stones musicians [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]; The musicians play for three circles of dancers [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]; The dancers were turned to stone for revelling (festivities) on a holy day [SUPPORTED: https://en.wikipedia.org/wiki/The_Pipers]"}]'::jsonb),
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'card_description', 'Y Garn Goch is a hill in the Brecon Beacons National Park in the east of Carmarthenshire.', 'On the hill of Y Garn Goch, the red cairn, lie two impressive Iron Age hillforts, the big fort and the little fort: in the established view, together the largest in southern Wales.', 'teaser-card-s008:454b824c-cc1a-4846-97d8-7c036712895b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '619f0626777fcc148540b521bc2d3adffc8af8801e88b67aa835fb8886cd5f0a|338f859ee51a72bc36c2c421bff15a43dc8f5b8105865c275abea656feb1e3d9|338f859ee51a72bc36c2c421bff15a43dc8f5b8105865c275abea656feb1e3d9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the hill of Y Garn Goch, the red cairn, lie two impressive Iron Age hillforts, the big fort and the little fort: in the established view, together the largest in southern Wales."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Y Garn Goch is a hill [S1]; the name means red cairn [S2]; two impressive Iron Age hillforts lie on it [S5]; the hillforts are the big fort and the little fort [S5]; in the established view they are together the largest in southern Wales [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Y Garn Goch is a hill with two Iron Age hillforts, the big fort and the little fort [SUPPORTED: https://en.wikipedia.org/wiki/Y_Garn_Goch]; The hill is named Y Garn Goch, meaning the red cairn [SUPPORTED: https://en.wikipedia.org/wiki/Y_Garn_Goch]; The two hillforts are impressive [SUPPORTED: https://en.wikipedia.org/wiki/Y_Garn_Goch]; In the established view the two forts together are the largest in southern Wales [SUPPORTED: https://en.wikipedia.org/wiki/Y_Garn_Goch]; The two hillforts together are the largest in southern Wales [SUPPORTED: https://en.wikipedia.org/wiki/Y_Garn_Goch]"}]'::jsonb),
    ('4624b081-fd19-48f9-a93d-a6f74ede6c01'::uuid, 'card_description', '2nd century AD Roman temple in Melite, built from marble with a tetrastyle portico — possibly on an earlier Punic sacred site. A 1747 inscription confirms a private benefactor funded its construction.', 'In the city of Melite stood the Temple of Apollo, a Roman temple of marble with Ionic columns, overlooking a semi-circular theatre. Parts of it were rediscovered in 2002, in modern Mdina.', 'teaser-card-s008:4624b081-fd19-48f9-a93d-a6f74ede6c01:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f58b08b397d34a8aea97171adba5bbabe6ba5d7847ba666fee92aa00dd3e8e0c|a6f58447790a21a45ec43a8645430c7d9a52b678444d018c0ee848a204ee9ecf|a6f58447790a21a45ec43a8645430c7d9a52b678444d018c0ee848a204ee9ecf', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the city of Melite stood the Temple of Apollo, a Roman temple of marble with Ionic columns, overlooking a semi-circular theatre. Parts of it were rediscovered in 2002, in modern Mdina."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple stood in the city of Melite [S1]; it was a Roman temple [S1]; it was built of marble [S4]; it had Ionic columns [S4]; it overlooked a semi-circular theatre [S5]; parts of it were rediscovered in 2002 [S3]; it is in modern Mdina [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Apollo was a Roman temple in the city of Melite (modern Mdina, Malta) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; The temple was built of marble [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; The temple had Ionic columns [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; The temple overlooked a semi-circular theatre [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; Parts of the temple were rediscovered in 2002 [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; In March 2002 a wall of the temple''s crepidoma was discovered in Villegaignon Street [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)]; Villegaignon Street, where the 2002 find was made, is a street in Mdina (so the rediscovery was in modern Mdina) [SUPPORTED: https://en.wikipedia.org/wiki/Mdina]"}]'::jsonb),
    ('4641bd18-a6d7-4f26-b895-e67f50af8e53'::uuid, 'card_description', 'An ancient port at the head of the Persian Gulf, capital of the kingdom of Characene. Founded around 324 BC, it linked Mesopotamian trade to Indian Ocean shipping.', 'At the head of the Persian Gulf lay the port of Charax Spasinu, first named Alexandria and perhaps founded by Alexander himself. Flooding destroyed it, and it was rebuilt circa 166 BC.', 'teaser-card-s008:4641bd18-a6d7-4f26-b895-e67f50af8e53:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'f2e6aaa9d921a40a9189b1b2ee6b6388e18dd70fac83d5e9649f026f4c7e463a|163743ba21c54aa623dd327501347ed21b4767a8947015c9595d92d4688ed943|163743ba21c54aa623dd327501347ed21b4767a8947015c9595d92d4688ed943', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At the head of the Persian Gulf lay the port of Charax Spasinu, first named Alexandria and perhaps founded by Alexander himself. Flooding destroyed it, and it was rebuilt circa 166 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a port at the head of the Persian Gulf [S1]; first named Alexandria [S2]; perhaps founded by Alexander himself [S2]; flooding destroyed it [S3]; it was rebuilt circa 166 BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Charax Spasinu was an ancient port at the head of the Persian Gulf (in present-day Iraq) [SUPPORTED: https://en.wikipedia.org/wiki/Charax_Spasinu]; The city was first named Alexandria (after Alexander the Great) [SUPPORTED: https://en.wikipedia.org/wiki/Charax_Spasinu]; Alexander himself perhaps founded it [SUPPORTED: https://en.wikipedia.org/wiki/Charax_Spasinu]; Flooding destroyed the city [SUPPORTED: https://en.wikipedia.org/wiki/Charax_Spasinu]; The city was rebuilt circa 166 BC [SUPPORTED: https://en.wikipedia.org/wiki/Charax_Spasinu]"}]'::jsonb),
    ('47c3b2a4-e476-4d38-b390-280c136fd1c5'::uuid, 'card_description', '600 BC-550 AD Maya city 40 km northeast of Tikal, with a 35 m pyramid, two ballcourts, and 24 stelae. Its Los Arboles complex bears Royal Jaguar Cult stucco imagery still being decoded by scholars.', 'Xultun has a 35 m tall pyramid and five large water reservoirs. Its excavations gave the only documented case of a Maya mathematician and astronomer whose name is deciphered: Sak Tahn Waax.', 'teaser-card-s008:47c3b2a4-e476-4d38-b390-280c136fd1c5:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '175c634c5152d8259221a7f8af59a74d205b58f6698a53b55a53298e01b43c58|32dc6695cd10d97ca7fd3bf81686ed4539961c11172b337335e18b4b8f200017|32dc6695cd10d97ca7fd3bf81686ed4539961c11172b337335e18b4b8f200017', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Xultun has a 35 m tall pyramid and five large water reservoirs. Its excavations gave the only documented case of a Maya mathematician and astronomer whose name is deciphered: Sak Tahn Waax."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a 35 m tall pyramid [S2]; five large water reservoirs [S2]; excavations gave the only documented case of a deciphered name of a Maya mathematician and astronomer [S6]; the name is Sak Tahn Waax [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Xultun is a Maya archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Xultun]; Xultun has a 35 m tall pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Xultun]; Xultun has five large water reservoirs [SUPPORTED: https://en.wikipedia.org/wiki/Xultun]; Excavations at Xultun gave the only documented case in which the name of a Maya mathematician and astronomer has been deciphered [SUPPORTED: https://en.wikipedia.org/wiki/Xultun]; The deciphered name of the Maya mathematician and astronomer is Sak Tahn Waax [SUPPORTED, no proving quote: https://www.smithsonianmag.com/smart-news/meet-sak-tahn-waax-a-maya-math-whiz-who-lived-more-than-1000-years-ago-and-left-behind-a-really-elegant-complex-formula-180989125/]"}]'::jsonb),
    ('48130c20-c762-482d-bf8f-1474186dda0f'::uuid, 'card_description', 'Triangular promontory in Wiltshire with steep natural defences on all sides except the south. Pottery found here is Roman or later -- the supposed Iron Age origin remains archaeologically unconfirmed.', 'On a triangular promontory beneath the Ridgeway, the earthworks of Bincknoll Castle appear to show a Norman motte and bailey, its motte now severely mutilated by later quarrying.', 'teaser-card-s008:48130c20-c762-482d-bf8f-1474186dda0f:card_description', 'teaser-card-s008 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'ce450834426141acb2fec195c8b2f6ed055be30388fb93a962e47d3ff35e6513|735c323a4307f2da27bc43903876b5c00a54c77f717d9e37994e84ad65435b01|735c323a4307f2da27bc43903876b5c00a54c77f717d9e37994e84ad65435b01', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a triangular promontory beneath the Ridgeway, the earthworks of Bincknoll Castle appear to show a Norman motte and bailey, its motte now severely mutilated by later quarrying."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "on a triangular promontory beneath the Ridgeway [S2]; the earthworks appear to show a Norman motte and bailey [S6]; the motte is severely mutilated by later quarrying [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bincknoll Castle is a Norman motte-and-bailey castle site (earthworks) in England (Wiltshire) [SUPPORTED: https://en.wikipedia.org/wiki/Bincknoll_Castle]; The site lies in England [SUPPORTED: https://en.wikipedia.org/wiki/Bincknoll_Castle]; It sits on a triangular promontory beneath the Ridgeway [SUPPORTED: https://en.wikipedia.org/wiki/Bincknoll_Castle]; The motte is now severely mutilated by later quarrying [SUPPORTED: https://en.wikipedia.org/wiki/Bincknoll_Castle]"}]'::jsonb),
    ('482a2a89-7c40-4f4d-a411-ab99de88b701'::uuid, 'card_description', 'Barren hills where Late Paleolithic and Mesolithic stone tools have been found scattered across the surface. These finds push human presence in the area back tens of thousands of years.', 'The last hunter-gatherers returned again and again to the Mulri Hills in Karachi. Late Palaeolithic and Mesolithic sites there are among Sindh''s most important finds of the last fifty years.', 'teaser-card-s008:482a2a89-7c40-4f4d-a411-ab99de88b701:card_description', 'teaser-card-s008 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'f38a6f4c1dd5ac569812fcc20905f23da7129ae599062c0bfc31fb3a236f46ef|56f7ad04243ed3e315c2dd1149d01bc3cbc227f83aa07b3eaa0e92358191dd70|56f7ad04243ed3e315c2dd1149d01bc3cbc227f83aa07b3eaa0e92358191dd70', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The last hunter-gatherers returned again and again to the Mulri Hills in Karachi. Late Palaeolithic and Mesolithic sites there are among Sindh''s most important finds of the last fifty years."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the last hunter-gatherers repeatedly inhabited the Mulri Hills [S3]; the hills are in Karachi [S1]; Late Palaeolithic and Mesolithic sites are there [S2]; they are among Sindh''s most important finds of the last fifty years [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Mulri Hills are hills in Karachi (Sindh, Pakistan) with archaeological sites [SUPPORTED: https://en.wikipedia.org/wiki/Mulri_Hills]; The last hunter-gatherers returned repeatedly to the Mulri Hills [SUPPORTED: https://en.wikipedia.org/wiki/Mulri_Hills]; Late Palaeolithic and Mesolithic sites were found on the Mulri Hills [SUPPORTED: https://en.wikipedia.org/wiki/Mulri_Hills]; These sites are among the most important archaeological discoveries in Sindh of the last fifty years [SUPPORTED: https://en.wikipedia.org/wiki/Mulri_Hills]"}]'::jsonb),
    ('48a6d6b8-7224-4edf-b20c-a6fba056d8fa'::uuid, 'card_description', 'Pentre Camp is an Iron Age hillfort, near the hamlet of Llangynyw and about 2.5 miles north-east of Llanfair Caereinion, in Powys.', 'In places five concentric ramparts ring Pentre Camp, an oval Iron Age hillfort in Powys. A spring at the base of its northern slope was probably of practical importance in where it stands.', 'teaser-card-s008:48a6d6b8-7224-4edf-b20c-a6fba056d8fa:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'c111a5fbe11791e6e3c3727893effa9dcef185f2baf0920f10e2aae779ec21d6|39f206984df21c29e5e66e0dad1932d150beac7c562a24e9f827f273a0f813d6|39f206984df21c29e5e66e0dad1932d150beac7c562a24e9f827f273a0f813d6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In places five concentric ramparts ring Pentre Camp, an oval Iron Age hillfort in Powys. A spring at the base of its northern slope was probably of practical importance in where it stands."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in places five concentric ramparts [S3]; an oval Iron Age hillfort in Powys [S1, S2]; a spring at the base of its northern slope [S7]; the spring was probably of practical importance to the fort''s location [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pentre Camp is an Iron Age hillfort in Powys (Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]; Pentre Camp lies in Powys, Wales [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]; The fort is oval [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]; In places five concentric ramparts ring the fort [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]; A spring lies at the base of the fort''s northern slope [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]; The spring was probably of practical importance in the fort''s location [SUPPORTED: https://en.wikipedia.org/wiki/Pentre_Camp]"}]'::jsonb),
    ('48bd1c07-897c-4699-9c14-73ce5b01fbd6'::uuid, 'card_description', 'Around 200 BC a Celtic oppidum of 49 hectares rose on the Staffelberg above the Main valley. Ptolemy recorded it as Menosgada — ''town above the Main valley'' — in his geographical writings.', 'Mentioned by Ptolemy, the Celtic metropolis of Menosgada probably stood on the Staffelberg, where around 200 BC an oppidum of 49 hectares was guarded by a 2,800-metre-long wall and ditch.', 'teaser-card-s008:48bd1c07-897c-4699-9c14-73ce5b01fbd6:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e9251add5caab706f42bec87a141aa57cd75828b8756a52de3ff1103dc76d694|1b8d84608aa608a2bacc08f3dca201fec1a8179adce5c744fefd4591b5206c05|1b8d84608aa608a2bacc08f3dca201fec1a8179adce5c744fefd4591b5206c05', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mentioned by Ptolemy, the Celtic metropolis of Menosgada probably stood on the Staffelberg, where around 200 BC an oppidum of 49 hectares was guarded by a 2,800-metre-long wall and ditch."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "mentioned by Ptolemy [S1]; a Celtic metropolis [S1]; it probably stood on the Staffelberg [S2]; around 200 BC an oppidum was made [S4]; the oppidum covered 49 hectares [S4]; a 2,800-metre-long wall and ditch protected it [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Menosgada was a Celtic metropolis (a Celtic oppidum settlement) on the Upper Main [SUPPORTED: https://en.wikipedia.org/wiki/Menosgada]; Menosgada is mentioned by Ptolemy [SUPPORTED: https://en.wikipedia.org/wiki/Menosgada]; Menosgada probably stood on the Staffelberg [SUPPORTED: https://en.wikipedia.org/wiki/Menosgada]; The Staffelberg is in Germany (Bavaria) [SUPPORTED: https://en.wikipedia.org/wiki/Staffelberg]; Around 200 BC the fortification was expanded into an oppidum of 49 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Menosgada]; The oppidum was protected by a 2,800-metre-long wall and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Menosgada]"}]'::jsonb),
    ('4bc8c850-b194-4d4a-b0a4-40f8c4ef762a'::uuid, 'card_description', 'Guyangdong, or Guyang Cave, or Old Sun Cave, is recorded as the oldest Longmen cave with carvings in the Northern Wei style.', 'The earliest history of the Longmen Grottoes is traced to the reign of Emperor Xiaowen of Northern Wei. Guyang Cave, the Old Sun Cave, is recorded as the oldest with Northern Wei carvings.', 'teaser-card-s008:4bc8c850-b194-4d4a-b0a4-40f8c4ef762a:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '03b9b7a5634e538b350f02204db4b50e9bd4e8034e41347f1db92a3182801386|62a9e332610f1f1cb7fede2de3a19fbeac4dc497d946e4cc5e193abafbab1061|62a9e332610f1f1cb7fede2de3a19fbeac4dc497d946e4cc5e193abafbab1061', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The earliest history of the Longmen Grottoes is traced to the reign of Emperor Xiaowen of Northern Wei. Guyang Cave, the Old Sun Cave, is recorded as the oldest with Northern Wei carvings."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the earliest history of the Longmen Grottoes is traced to the reign of Emperor Xiaowen of Northern Wei [S1]; Guyang Cave is also called the Old Sun Cave [S5]; Guyang Cave is recorded as the oldest cave with Northern Wei carvings [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Longmen Grottoes are a complex of Buddhist cave temples and rock carvings near Luoyang, Henan, China [SUPPORTED: https://en.wikipedia.org/wiki/Longmen_Grottoes]; The earliest history of the Longmen Grottoes is traced to the reign of Emperor Xiaowen of Northern Wei [SUPPORTED: https://en.wikipedia.org/wiki/Longmen_Grottoes]; Guyang Cave is also called the Old Sun Cave [SUPPORTED: https://en.wikipedia.org/wiki/Longmen_Grottoes]; Guyang Cave is recorded as the oldest Longmen cave with Northern Wei carvings [SUPPORTED: https://en.wikipedia.org/wiki/Longmen_Grottoes]"}]'::jsonb),
    ('4c6645cc-de9a-4a21-b932-809f7600337c'::uuid, 'card_description', 'Berry Head is a coastal headland that forms the southern boundary of Tor Bay in Devon.', 'On Berry Head, at the southern edge of Tor Bay, an Iron Age hill fort was mostly destroyed by fortifications raised between 1794 and 1804 against threatened invasion by French armies.', 'teaser-card-s008:4c6645cc-de9a-4a21-b932-809f7600337c:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '37b5436fe46c6f4aa59942a0eb26c8c4a822fcfc9f6474f76b52f43abe1c01b9|792124a29c22dd72d7858e969873822444dd047f0bd6245156d863738c5103e3|792124a29c22dd72d7858e969873822444dd047f0bd6245156d863738c5103e3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Berry Head, at the southern edge of Tor Bay, an Iron Age hill fort was mostly destroyed by fortifications raised between 1794 and 1804 against threatened invasion by French armies."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Berry Head, a headland at the southern edge of Tor Bay [S1]; there is an Iron Age hill fort on Berry Head [S3]; the hill fort was mostly destroyed [S3]; it was destroyed by fortifications built between 1794 and 1804 [S3]; the fortifications were made against threatened invasion by French armies [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Berry Head is the site of an Iron Age hill fort (central claim: a hill fort on a headland) [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Head]; Berry Head lies at the southern edge of Tor Bay [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Head]; The Iron Age hill fort was mostly destroyed by later fortifications [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Head]; The fortifications were built between 1794 and 1804 [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Head]; The fortifications were raised against threatened invasion by French armies [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Head]"}]'::jsonb),
    ('4caf5522-6a45-44b4-bba0-e98186c081f1'::uuid, 'card_description', 'A square 58-by-68-metre earthwork that may be a Roman marching camp or Iron Age civilian settlement. The heritage authority notes the interpretation, but firm evidence is still lacking.', 'Broadbury Castle, near Beaworthy in Devon, is a single bank and ditch around an almost square piece of ground, 58 by 68 metres. Roman marching camp, or civilian settlement?', 'teaser-card-s008:4caf5522-6a45-44b4-bba0-e98186c081f1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '10dc94f5aa1b85d3ada604e736771af31d8e0019a6b29f4c66a8578425918326|065f65bf91a5d4a4e8cc01aef9f5c63449b2fdf23417736588e28c8d93bd8a01|065f65bf91a5d4a4e8cc01aef9f5c63449b2fdf23417736588e28c8d93bd8a01', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Broadbury Castle, near Beaworthy in Devon, is a single bank and ditch around an almost square piece of ground, 58 by 68 metres. Roman marching camp, or civilian settlement?"}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Broadbury Castle is near Beaworthy in Devon [S1]; the site is a single bank and ditch [S2]; the bank and ditch enclose an almost square piece of ground [S2]; the enclosed ground measures 58 by 68 metres [S2]; one interpretation is a Roman marching camp [S3]; another interpretation is a civilian settlement [S3]; the question implies the site''s function is uncertain or disputed between those two readings [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Broadbury Castle is an archaeological earthwork (an enclosure) (central claim: kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; It lies near Beaworthy [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; It lies in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; The site is a single bank and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; The bank and ditch enclose an almost square piece of ground [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; The enclosed ground measures 58 by 68 metres [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; It has been interpreted as a Roman marching camp [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; An alternative interpretation as a civilian settlement has been proposed [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]; Its function is uncertain: firm evidence for the Roman camp is lacking (the text''s question mark) [SUPPORTED: https://en.wikipedia.org/wiki/Broadbury_Castle]"}]'::jsonb),
    ('4cb6f3b9-1169-4e17-ae90-a012b3b6d3e4'::uuid, 'card_description', 'Four roundhouses and a granary rebuilt on their original Iron Age foundations near Nevern in Pembrokeshire. Prehistoric farming experiments continue at this living archaeology site.', 'At Castell Henllys, four roundhouses and a granary stand again on their original Iron Age foundations, some 2,000 years old, the only site in Britain where this has been done.', 'teaser-card-s008:4cb6f3b9-1169-4e17-ae90-a012b3b6d3e4:card_description', 'teaser-card-s008 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'db382252c8d4bd270b46bdd48825a40908c8b62236873ceb27bf7f43ce61cba0|c58275934b675b7a56f5a1ce017a9101c7b371f41e5b04e456db8c1a26a6af04|c58275934b675b7a56f5a1ce017a9101c7b371f41e5b04e456db8c1a26a6af04', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Castell Henllys, four roundhouses and a granary stand again on their original Iron Age foundations, some 2,000 years old, the only site in Britain where this has been done."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Castell Henllys [S1]; four roundhouses and a granary have been reconstructed [S3]; they stand on their original Iron Age foundations [S3]; the foundations are some 2,000 years old [S3]; it is the only site in Britain where this has been done [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Castell Henllys is an Iron Age hillfort / archaeological site (central claim: kind of place; in north Pembrokeshire, Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Henllys]; Castell Henllys is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Henllys]; Four roundhouses and a granary have been reconstructed and stand on their original Iron Age foundations [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Henllys]; The original Iron Age foundations are some 2,000 years old [SUPPORTED: https://www.pembrokeshirecoast.wales/castell-henllys/about-castell-henllys/]; Castell Henllys is the only site in Britain where this (reconstruction on original Iron Age foundations) has been done [SUPPORTED: https://www.pembrokeshirecoast.wales/castell-henllys/about-castell-henllys/]; Castell Henllys is the only site in Britain where four roundhouses and a granary were rebuilt on their original foundations (some 2,000 years old) [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Henllys]"}]'::jsonb),
    ('4cdbbcf7-6cdf-4295-be70-8f77b1e92bf4'::uuid, 'card_description', 'A Roman fort built on a mountain pass between 120 and 138 AD, garrisoned by troops from the Dalmatian coast. A parade ground leveled into the steep hillside still survives.', NULL, 'teaser-card-s008:4cdbbcf7-6cdf-4295-be70-8f77b1e92bf4:card_description', 'teaser-card-s008 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||a722ef88bb4eba61772685439fd87813bc1290217144d6748d0b94be7652f440', '[{"source": "lane WB run wb-ws-2026-09-27-04: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check could not prove: Hardknott Roman Fort is a Roman fort (central claim), on the Hardknott Pass in the English Lake District; The web check could not prove: Hardknott Roman Fort is a Roman fort in England (Lake District, Cumbria)"}]'::jsonb),
    ('4dc7086c-f261-4f38-85f2-10a20eeda1bc'::uuid, 'card_description', 'The cave complex is noted for one of the best preserved floors from the Paleolithic containing more than 4,000 fossils and more than 500 graphical units.', 'At La Garma Cave Complex, a rockslide sealed the original entrance about 16,000 years ago, keeping a Paleolithic floor pristine: more than 4,000 fossils, and an ibex carved on a bovine rib.', 'teaser-card-s008:4dc7086c-f261-4f38-85f2-10a20eeda1bc:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '7f026f79edc3629863e643d07e5908edec072adecdc40aa407cc5c7f36d883cd|5f1ee34d92da9f7f5805bb058f94ae751a812d103aebc5333552d7b696220202|5f1ee34d92da9f7f5805bb058f94ae751a812d103aebc5333552d7b696220202', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At La Garma Cave Complex, a rockslide sealed the original entrance about 16,000 years ago, keeping a Paleolithic floor pristine: more than 4,000 fossils, and an ibex carved on a bovine rib."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is the La Garma Cave Complex [S1]; a rockslide sealed the original entrance [S5]; the sealing happened about 16,000 years ago [S5]; the sealing kept the cave floor pristine [S5]; the floor is a Paleolithic floor [S2]; the floor holds more than 4,000 fossils [S2]; an ibex is carved on a bovine rib [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Garma is a cave complex (a parietal art-bearing paleoanthropological cave system in Cantabria, Spain) (central claim: kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; A rockslide sealed the original entrance (of the Lower Gallery) [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; The rockslide happened about 16,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; The sealing kept the cave floor pristine [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; The floor is a Paleolithic floor, one of the best preserved [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; The original entrance was blocked by a collapse, making the cave a prehistoric time capsule (second source) [SUPPORTED: https://fundacionpalarq.com/en/la-garma/]; The complex holds more than 4,000 fossils [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; An ibex depiction is carved (among the portable art found) [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]; The ibex is carved on a bovine rib [SUPPORTED: https://en.wikipedia.org/wiki/La_Garma_cave_complex]"}]'::jsonb),
    ('4df3dcbd-62d3-4e37-92fe-e79989233f1f'::uuid, 'card_description', '700-1600 AD rock art site with cave paintings and engravings inside a Sonoran Desert canyon, plus seasonal camps on the alluvial plain. La Pintada spans nearly a millennium of human artistic activity.', 'In a canyon of the Sierra Libre, La Pintada holds cave paintings and rock engravings, while on the plain outside lie traces of seasonal camps strewn with ceramics and stone tools.', 'teaser-card-s008:4df3dcbd-62d3-4e37-92fe-e79989233f1f:card_description', 'teaser-card-s008 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '637708755a1609fe77b82431ed8f6845dee6ef73b71ea392beb409926289d8a3|b64bd62db236cfbec60d4a902f3704f063d382c53175dc5896dcaf93db201b30|b64bd62db236cfbec60d4a902f3704f063d382c53175dc5896dcaf93db201b30', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In a canyon of the Sierra Libre, La Pintada holds cave paintings and rock engravings, while on the plain outside lie traces of seasonal camps strewn with ceramics and stone tools."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Pintada lies in a canyon of the Sierra Libre [S1]; the canyon holds cave paintings [S2]; the canyon holds rock engravings [S2]; on the plain outside the canyon lie traces of seasonal camps [S2]; the camp area is strewn with ceramics and stone tools [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Pintada is an archaeological site (cave paintings and rock engravings with open-air camp remains) in Sonora, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/La_Pintada_(archaeological_site)]; The site lies within a canyon that is part of the Sierra Libre [SUPPORTED: https://en.wikipedia.org/wiki/La_Pintada_(archaeological_site)]; La Pintada holds cave paintings and rock engravings in the canyon [SUPPORTED: https://en.wikipedia.org/wiki/La_Pintada_(archaeological_site)]; Outside the canyon, on the plain, lie traces of seasonal camps [SUPPORTED: https://en.wikipedia.org/wiki/La_Pintada_(archaeological_site)]; The camp remains are strewn with ceramics and stone tools [SUPPORTED: https://en.wikipedia.org/wiki/La_Pintada_(archaeological_site)]"}]'::jsonb),
    ('4df5f7bf-8b73-4602-9d6e-dab158203820'::uuid, 'card_description', 'A Preclassic Maya city active from 1000 BC to 200 AD, now buried under a modern village. Residents literally walk on top of their ancient predecessors every day.', 'On a plateau below volcanic ridges, Chocolá''s stone-lined canals once brought water from underground springs to elite residences, while pyramidal mounds up to 25 meters rose further south.', 'teaser-card-s008:4df5f7bf-8b73-4602-9d6e-dab158203820:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a84084c9335cc0b304adfe55e317a9200013093843e37be70add3bdef3a04359|d4580019144e931e90d533c24a13051046ae9295ac51d868f5a01b7c44fd6a67|d4580019144e931e90d533c24a13051046ae9295ac51d868f5a01b7c44fd6a67', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a plateau below volcanic ridges, Chocolá''s stone-lined canals once brought water from underground springs to elite residences, while pyramidal mounds up to 25 meters rose further south."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chocola lies on a plateau below volcanic ridges [S3]; stone-lined canals brought water from underground springs [S4]; the water went to elite residences [S4]; the canals are in the past (once) [S4]; pyramidal mounds up to 25 meters high rose further south [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chocolá is a Preclassic Southern Maya site (an ancient settlement with elite residences, administrative and commoner sectors) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Chocol%C3%A1]; Chocolá lies in Suchitepéquez Department, Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Chocol%C3%A1]; The site lies on a plateau below volcanic ridges [SUPPORTED: https://en.wikipedia.org/wiki/Chocol%C3%A1]; In the north of the site, elite residences were supplied by stone-lined canals bringing water from underground springs [SUPPORTED: https://en.wikipedia.org/wiki/Chocol%C3%A1]; Pyramidal mounds up to 25 meters lie in the central district, further south [SUPPORTED: https://en.wikipedia.org/wiki/Chocol%C3%A1]"}]'::jsonb),
    ('4eba8602-4117-47ee-9c24-7e0ab06ef999'::uuid, 'card_description', 'A 4500 BC dolmen with a capstone 5.5 metres long balanced on three uprights. It collapsed in an 1815 storm and was re-erected, but now stands shorter than the original.', 'In the eighteenth century a rider on horseback could pass beneath Lanyon Quoit. A storm brought it down in 1815, and now its capstone of more than 12 tonnes rests on just three stones.', 'teaser-card-s008:4eba8602-4117-47ee-9c24-7e0ab06ef999:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '0fc205243da7d16704ea7b7ec3cae0d9e486f1464abc2ff5edd238c792355dc3|f30b26e775670fce9309ccf01cd0dc8509e3458ec8046fd85cff3d78d7c0c57d|f30b26e775670fce9309ccf01cd0dc8509e3458ec8046fd85cff3d78d7c0c57d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the eighteenth century a rider on horseback could pass beneath Lanyon Quoit. A storm brought it down in 1815, and now its capstone of more than 12 tonnes rests on just three stones."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in the eighteenth century a rider on horseback could pass beneath Lanyon Quoit [S5]; a storm brought it down in 1815 [S2]; its capstone weighs more than 12 tonnes [S4]; the capstone now rests on just three stones [S3, S4, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Lanyon Quoit is a dolmen (quoit) in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Lanyon_Quoit]; In the eighteenth century the structure was tall enough for a person on horseback to ride under it [SUPPORTED: https://en.wikipedia.org/wiki/Lanyon_Quoit]; A storm brought the quoit down in 1815 [SUPPORTED: https://en.wikipedia.org/wiki/Lanyon_Quoit]; Its capstone weighs more than 12 tonnes [SUPPORTED: https://en.wikipedia.org/wiki/Lanyon_Quoit]; The capstone now rests on just three stones [SUPPORTED: https://en.wikipedia.org/wiki/Lanyon_Quoit]"}]'::jsonb),
    ('4faa104c-1f92-4968-aa85-ec1450813997'::uuid, 'card_description', 'Rock painting site in the Andes above Cusco, spread across multiple named sectors on mountain slopes. The Llamachayuq Qaqa section is dominated by llama figures painted across an open cliff face.', 'On the slope of the mountain Muruwiksa, in the Pisac District, the principal paintings of Chawaytiri show mostly llamas. Other sections bear names such as Wamanwachana and Kawituyuq.', 'teaser-card-s008:4faa104c-1f92-4968-aa85-ec1450813997:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'bcacac3343f1d6c03ed5d7403ae1ff414984e20b68b6d787a8ef59bf15ab1b87|5ffce783e4ec2ee791fb8357d10be93b8f54632d92ec9d0e88ca3b53e79899fb|5ffce783e4ec2ee791fb8357d10be93b8f54632d92ec9d0e88ca3b53e79899fb', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the slope of the mountain Muruwiksa, in the Pisac District, the principal paintings of Chawaytiri show mostly llamas. Other sections bear names such as Wamanwachana and Kawituyuq."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the principal section lies on the slope of the mountain Muruwiksa [S3, S4]; the site is in the Pisac District [S2]; the principal paintings show mostly llamas [S3]; there are other sections [S5]; other sections are named Wamanwachana and Kawituyuq [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chawaytiri is a rock-painting archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Chawaytiri]; The site is in the Pisac District [SUPPORTED: https://en.wikipedia.org/wiki/Chawaytiri]; The principal section with paintings mostly shows llamas [SUPPORTED: https://en.wikipedia.org/wiki/Chawaytiri]; The principal section lies on the slope of the mountain Muruwiksa [SUPPORTED: https://en.wikipedia.org/wiki/Chawaytiri]; Other sections are named Wamanwachana and Kawituyuq [SUPPORTED: https://en.wikipedia.org/wiki/Chawaytiri]"}]'::jsonb),
    ('5075fcfd-fd0b-4b63-ae8d-7d43e1964554'::uuid, 'card_description', 'The pottery in the tomb dates to around 1500 to 1450 BC, but the gold and carved gem seals might have been old when buried.', 'South of Sparta, the beehive tomb of Vaphio yielded two golden cups whose reliefs show bulls being captured, perhaps for the bull-leaping of Minoan Crete, perhaps for sacrifice.', 'teaser-card-s008:5075fcfd-fd0b-4b63-ae8d-7d43e1964554:card_description', 'teaser-card-s008 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'a7eafdbe9dfba0ca82be5ac630be06a89594dbce11463a61b6030140df134b61|eb2a5da38a57ad31fe4c548a81cd9bd2988dc29cb88fd83db93bb73efdee918e|eb2a5da38a57ad31fe4c548a81cd9bd2988dc29cb88fd83db93bb73efdee918e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "South of Sparta, the beehive tomb of Vaphio yielded two golden cups whose reliefs show bulls being captured, perhaps for the bull-leaping of Minoan Crete, perhaps for sacrifice."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vaphio lies south of Sparta [S1]; Vaphio has a beehive (tholos) tomb [S2]; the tomb yielded two golden cups [S7]; the cups'' reliefs show bulls being captured [S7]; the capture was perhaps for the bull-leaping of Minoan Crete [S7]; or perhaps for sacrifice [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vaphio is a site famous for its tholos (beehive) tomb [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]; The site lies south of Sparta (Laconia, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]; The tomb yielded a pair of golden cups [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]; The reliefs show bulls being captured [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]; The capture scenes are perhaps connected with the bull-leaping of Minoan Crete [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]; The capture scenes are perhaps connected with sacrifice [SUPPORTED: https://en.wikipedia.org/wiki/Vaphio]"}]'::jsonb),
    ('5077f16f-1d87-4be3-a870-35f3e1cf55fe'::uuid, 'card_description', 'The tomb was constructed of glacial erratic boulders and dates back to the New Stone Age in Rügen.', 'Just a few metres from the steep coast of Tromper Wiek, the Riesenberg at Nobbin, a New Stone Age tomb of glacial erratic boulders, is one of the largest stone graves in North Germany.', 'teaser-card-s008:5077f16f-1d87-4be3-a870-35f3e1cf55fe:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '7ef577c64b2dcc85c3f05bd66534f31fb7a2843052fc85c30b6a266d417ad8a3|10a70d7e8ef81e50c3cdfe0be613ae65194e657c1fc4cfb2adc193cb44ec7dda|10a70d7e8ef81e50c3cdfe0be613ae65194e657c1fc4cfb2adc193cb44ec7dda', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Just a few metres from the steep coast of Tromper Wiek, the Riesenberg at Nobbin, a New Stone Age tomb of glacial erratic boulders, is one of the largest stone graves in North Germany."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the tomb lies just a few metres from the steep coast of Tromper Wiek [S3]; the Riesenberg is at Nobbin [S1]; it is a New Stone Age tomb [S2]; it is made of glacial erratic boulders [S2]; it is one of the largest stone graves in North Germany [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Riesenberg at Nobbin is a megalithic tomb [SUPPORTED: https://en.wikipedia.org/wiki/Nobbin]; The tomb is built of glacial erratic boulders [SUPPORTED: https://en.wikipedia.org/wiki/Nobbin]; The tomb dates to the New Stone Age [SUPPORTED: https://en.wikipedia.org/wiki/Nobbin]; It is one of the largest stone graves in North Germany [SUPPORTED: https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin]; It lies just a few metres from the steep coast of Tromper Wiek [SUPPORTED: https://en.wikipedia.org/wiki/Nobbin]"}]'::jsonb),
    ('50d4292b-caee-4819-8aaa-64b94187fce8'::uuid, 'card_description', 'The most ancient burials at the Serapeum, found in isolated tombs, date back to the reign of Amenhotep III of the Eighteenth Dynasty in the 14th century BC.', 'At Memphis, the sacred bulls of the Apis cult were buried in the Serapeum of Saqqara. In 1850 Auguste Mariette rediscovered it and found two Apis burials that no one had disturbed.', 'teaser-card-s008:50d4292b-caee-4819-8aaa-64b94187fce8:card_description', 'teaser-card-s008 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f1d43e1ce3f282e82f23b5e04fea6cf006eeea7eba39baaf2f9ef891855a6e80|06b9a07cf24b3cd625baf392f2f8bc92eb6491f5083339c48a8479ba343b9843|06b9a07cf24b3cd625baf392f2f8bc92eb6491f5083339c48a8479ba343b9843', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Memphis, the sacred bulls of the Apis cult were buried in the Serapeum of Saqqara. In 1850 Auguste Mariette rediscovered it and found two Apis burials that no one had disturbed."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the sacred bulls of the Apis cult at Memphis were buried in the Serapeum of Saqqara [S1]; Auguste Mariette rediscovered the Serapeum in 1850 [S3]; he found two Apis burials [S4]; those two burials had not been disturbed [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Serapeum of Saqqara was the burial place of the sacred bulls of the Apis cult [SUPPORTED: https://en.wikipedia.org/wiki/Serapeum_of_Saqqara]; The Serapeum is at Memphis (Saqqara) [SUPPORTED: https://en.wikipedia.org/wiki/Serapeum_of_Saqqara]; Auguste Mariette rediscovered the Serapeum [SUPPORTED: https://en.wikipedia.org/wiki/Serapeum_of_Saqqara]; The rediscovery took place in 1850 [SUPPORTED: https://en.wikipedia.org/wiki/Serapeum_of_Saqqara]; Mariette found two Apis burials that had not been disturbed [SUPPORTED: https://en.wikipedia.org/wiki/Serapeum_of_Saqqara]"}]'::jsonb),
    ('524ad4af-2109-4994-8881-1ecd527ee65c'::uuid, 'card_description', 'Ordered by Emperor Trajan and built 104–106 AD across the Tagus, this stone arch bridge has lost more spans to war than to weather — the Moors, then later European armies all blew pieces off it.', 'Built over the Tagus between 104 and 106 AD at the order of Trajan, the Alcántara Bridge was broken by the Moors, the Spanish, Wellington''s forces and the Carlists, and rose again.', 'teaser-card-s008:524ad4af-2109-4994-8881-1ecd527ee65c:card_description', 'teaser-card-s008 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '3abcf1298d44726c62026be65cc35971c0e31ebbc0d0dc7c9fbaf2e97b4368e6|73bb069fd66c70af48387e846f81bd730e261939312c39278537beec265194c6|73bb069fd66c70af48387e846f81bd730e261939312c39278537beec265194c6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built over the Tagus between 104 and 106 AD at the order of Trajan, the Alcántara Bridge was broken by the Moors, the Spanish, Wellington''s forces and the Carlists, and rose again."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the bridge was built over the Tagus [S2]; it was built between 104 and 106 AD [S2]; it was built at the order of Trajan [S2]; the Moors broke (destroyed part of) it [S3]; the Spanish broke (destroyed part of) it [S4]; Wellington''s forces broke (blew up part of) it [S4]; the Carlists broke (destroyed much of) it [S5]; it was repaired or rebuilt each time and stands again [S3, S4, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Alcántara Bridge is a Roman bridge at Alcántara (a bridge is the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The Alcántara Bridge is a stone arch bridge built over the Tagus between 104 and 106 AD [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The bridge was built at the order of the Roman emperor Trajan [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The Moors broke (destroyed) part of the bridge [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The Spanish broke part of the bridge [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; Wellington''s forces broke (blew up) part of the bridge [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The Carlists broke (destroyed) much of the bridge [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]; The bridge was rebuilt (rose again) [SUPPORTED: https://en.wikipedia.org/wiki/Alc%C3%A1ntara_Bridge]"}]'::jsonb),
    ('52c6e083-90a9-44d1-83f8-d3c2cbd0e9e3'::uuid, 'card_description', 'A passage grave built with heavy boulders and capstones, assigned to the Funnelbeaker culture. The cemetery also contains unchambered long barrows and other tumuli.', 'In Western Pomerania, the Borkowo Megalithic Cemetery gathers long barrows and a passage grave of heavy boulders and capstones, where excavators found a cremation and a few pottery sherds.', 'teaser-card-s008:52c6e083-90a9-44d1-83f8-d3c2cbd0e9e3:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'db821eabd31f4b410fe835bff9154cd4c741e950be4430caf19d2b18c78707b3|22c2ef5bd3bc2e9b17002e8a6a3605682b60213af14db18197597c9f52568ceb|22c2ef5bd3bc2e9b17002e8a6a3605682b60213af14db18197597c9f52568ceb', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Western Pomerania, the Borkowo Megalithic Cemetery gathers long barrows and a passage grave of heavy boulders and capstones, where excavators found a cremation and a few pottery sherds."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the cemetery is in Western Pomerania [S1]; it contains long barrows [S2]; it contains a passage grave [S2]; the passage grave is made of heavy boulders and capstones [S3]; excavations found a cremation [S5]; excavations found a few pottery sherds [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Borkowo Megalithic Cemetery is a prehistoric burial ground (a megalithic cemetery) [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; The cemetery lies in Western Pomerania [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; The cemetery has long barrows [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; The cemetery has a passage grave [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; The passage grave is made of heavy boulders and capstones [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; Excavators found a cremation [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]; Excavators found a few pottery sherds [SUPPORTED: https://en.wikipedia.org/wiki/Borkowo_megalithic_cemetery]"}]'::jsonb),
    ('539b56ad-5705-40c1-848b-767710247e7c'::uuid, 'card_description', 'A Neolithic burial chamber capped by a massive roof slab estimated at 25 tonnes. Inside, the remains of 15 to 30 people were found — a communal tomb used over generations.', 'Under a roof slab estimated at 25 tonnes, the uprights of Lligwy Burial Chamber on Anglesey hide half their height underground. In 1909 excavators found the remains of some 15 to 30 people.', 'teaser-card-s008:539b56ad-5705-40c1-848b-767710247e7c:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '36d096ed89d5f5e1f1614f2dec885c874c74185568a2b431f78d34b3cf6f5cdc|237e5a950ee7e144205d7c160317986122f6f515b062be5d7f72aec32cd429f5|237e5a950ee7e144205d7c160317986122f6f515b062be5d7f72aec32cd429f5', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Under a roof slab estimated at 25 tonnes, the uprights of Lligwy Burial Chamber on Anglesey hide half their height underground. In 1909 excavators found the remains of some 15 to 30 people."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the roof slab is estimated at 25 tonnes [S2, S6]; the uprights hide half their height underground [S4]; the chamber is on Anglesey [S1]; in 1909 excavators found remains of some 15 to 30 people [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Lligwy Burial Chamber is a burial chamber (a Neolithic chambered tomb) on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Lligwy_Burial_Chamber]; A roof slab (capstone) of the chamber is estimated at 25 tonnes [SUPPORTED: https://en.wikipedia.org/wiki/Lligwy_Burial_Chamber]; The chamber is built partly underground, so its uprights are partly buried [SUPPORTED: http://www.stone-circles.org.uk/stone/lligwy.htm]; About half of the height of the uprights lies below the surface (hidden underground) [SUPPORTED: http://www.stone-circles.org.uk/stone/lligwy.htm]; Excavations in 1909 found remains of some 15 to 30 people [SUPPORTED: https://en.wikipedia.org/wiki/Lligwy_Burial_Chamber]"}]'::jsonb),
    ('53e3bad0-669e-4cbf-8aef-031dd53e84df'::uuid, 'card_description', 'The national monument consists of the ruins of multiple structures surrounded by a compound wall, constructed by the ancient people of the Hohokam period.', 'Its name means big house: Casa Grande Ruins National Monument, the caliche shell of a four-story Hohokam structure that has outlasted extreme desert weather for about seven centuries.', 'teaser-card-s008:53e3bad0-669e-4cbf-8aef-031dd53e84df:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'f04a810ac0e4e7b59d472ca848ee2c76f7700deae91c799c274e5ea41829bebf|54da74627445be833c630e18d24762a6ada4e28c11fbd5a56261636b8ca34d9f|54da74627445be833c630e18d24762a6ada4e28c11fbd5a56261636b8ca34d9f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Its name means big house: Casa Grande Ruins National Monument, the caliche shell of a four-story Hohokam structure that has outlasted extreme desert weather for about seven centuries."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the name ''Casa Grande'' means big house [S5]; the name refers to the largest structure on the site [S6]; the site is Casa Grande Ruins National Monument [S1]; the structure is Hohokam [S1, S2]; what remains of the structure is a four-story structure''s remnant (shell) [S6]; the structure is made of caliche [S7]; the structure was four stories high [S6]; it has survived extreme weather conditions [S7]; the setting is the desert (Sonoran Desert) [S4]; it has survived for about seven centuries [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Casa Grande Ruins National Monument is a site preserving a group of Hohokam structures (an ancient Hohokam settlement complex), in Coolidge, Arizona, USA [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The site lies in Coolidge, Arizona (USA) [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The name Casa Grande means ''big house'' [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The name refers to the largest structure on the site, the one the text describes [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The structure is what remains of (a shell of) a four-story structure [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The structure is made of caliche [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The structure was built by the Hohokam [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The structure has survived extreme weather conditions [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The structure has survived for about seven centuries [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]; The setting is a desert (the Hohokam builders were people of the ancient Sonoran Desert) [SUPPORTED: https://en.wikipedia.org/wiki/Casa_Grande_Ruins_National_Monument]"}]'::jsonb),
    ('54559aae-1d96-48f0-a2c0-9790d7ee7c20'::uuid, 'card_description', 'The largest Iron Age gravefield in Bohuslän with 220 graves from the Migration Period (400–500 AD). Finds include glass beads and bone combs from the age of great migrations.', 'Among the 220 graves of Greby Grave Field, the largest site of its kind in Bohuslän, lay glass pearls and bone combs from approximately 400-500 AD. Newer finds hint at a trading site.', 'teaser-card-s008:54559aae-1d96-48f0-a2c0-9790d7ee7c20:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '0c835e2d1f32c51c5ead279a1eab52ff670a12269658235db6c532f0ffbb6ce0|613ca4c1debfda8eadafa956d7c18161d6d7037cbf8471998134c9240c0d828e|613ca4c1debfda8eadafa956d7c18161d6d7037cbf8471998134c9240c0d828e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Among the 220 graves of Greby Grave Field, the largest site of its kind in Bohuslän, lay glass pearls and bone combs from approximately 400-500 AD. Newer finds hint at a trading site."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Greby Grave Field [S1]; the site has 220 graves [S3]; it is the largest site of its kind in Bohuslän [S3]; glass pearls were found in the graves [S5]; bone combs were found in the graves [S5]; the grave objects date from approximately 400-500 AD [S5]; newer finds hint (hedged) that the site may have been a trading site [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Greby Grave Field is an Iron Age grave field in western Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; The grave field is in Bohuslän (Tanum Municipality, Västra Götaland County) [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; The grave field has 220 graves [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; It is the largest site of its kind in Bohuslän [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; Glass pearls (beads) were found in the graves [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; Bone combs were found in the graves [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; The finds date to approximately 400-500 AD [SUPPORTED: https://en.wikipedia.org/wiki/Greby]; Newer finds hint that Greby was a trading site [SUPPORTED: https://en.wikipedia.org/wiki/Greby]"}]'::jsonb),
    ('55ce644f-cbfa-4aab-9f3f-e7cca251f3ad'::uuid, 'card_description', 'Chan Chan is located in the mouth of the Moche Valley and was the capital of the historical empire of the Chimor from 900 to 1470.', 'Once the largest city of pre-Columbian South America, Chan Chan spanned 20 square kilometers, its ciudadelas housing plazas, storerooms and burial platforms for the royals of Chimor.', 'teaser-card-s008:55ce644f-cbfa-4aab-9f3f-e7cca251f3ad:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '9f294f788cb22d968e02c912f8029786f8c52d766754ecf1eccdc8104588b57f|c9abcde0ba981a508f64817fda1c3214b828665bed27d5dd43962059834f5a9d|c9abcde0ba981a508f64817fda1c3214b828665bed27d5dd43962059834f5a9d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Once the largest city of pre-Columbian South America, Chan Chan spanned 20 square kilometers, its ciudadelas housing plazas, storerooms and burial platforms for the royals of Chimor."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Chan Chan [S1]; Chan Chan was the largest city of pre-Columbian South America [S2]; this is a past state (''once''): the city is now an archaeological site / declined [S3, S7]; the city spanned 20 square kilometers [S5]; the city had ciudadelas [S5]; the ciudadelas housed plazas [S6]; the ciudadelas housed storerooms [S6]; the ciudadelas housed burial platforms for the royals [S6]; the royals belonged to Chimor, of which Chan Chan was the capital [S1, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chan Chan is a (pre-Columbian) city, now an archaeological site, in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; Chan Chan is in Peru (five kilometers west of Trujillo) [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; Chan Chan was once the largest city of pre-Columbian South America [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; Chan Chan spanned 20 square kilometers [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; Chan Chan had ciudadelas [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; The ciudadelas housed plazas [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; The ciudadelas housed storerooms [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; The ciudadelas housed burial platforms for the royals [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; Chan Chan was the capital of Chimor (so the royals were those of Chimor) [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]; The city dates to the pre-Columbian period, capital of Chimor until the Inca conquest c. 1470 (so ''once'' the largest: it later declined) [SUPPORTED: https://en.wikipedia.org/wiki/Chan_Chan]"}]'::jsonb),
    ('565483ad-e6c8-4053-9d06-dfd254daa246'::uuid, 'card_description', 'A Jeulmun pottery-period shell midden on Yeong-do Island in Busan — among the oldest such deposits in the region. Three excavations from 1969 recovered mollusc shells, fish bones, and pottery.', 'Shells heaped on Yeong-do Island by people of the Jeulmun pottery period form the Shell Mound in Dongsam-dong, among the oldest Jeulmun middens yet found in the southern Korean Peninsula.', 'teaser-card-s008:565483ad-e6c8-4053-9d06-dfd254daa246:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '602b33efa6d292f44025cac38d984adf4943ecd7a108e7a7643a260890ad6b03|43ba438c097da1089e6226ab8f05ca2cf1e59607d6e4ca2420e94321557594de|43ba438c097da1089e6226ab8f05ca2cf1e59607d6e4ca2420e94321557594de', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Shells heaped on Yeong-do Island by people of the Jeulmun pottery period form the Shell Mound in Dongsam-dong, among the oldest Jeulmun middens yet found in the southern Korean Peninsula."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is the Shell Mound in Dongsam-dong [S1]; the site consists of shells heaped/discarded in a restricted area (a midden) [S2]; it lies on Yeong-do Island [S1]; the shells were discarded by people of the Jeulmun pottery period [S2]; it is among the oldest Jeulmun middens found so far [S3]; the finding place of those middens is the southern Korean Peninsula [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Shell Mound in Dongsam-dong is an archaeological site consisting of a shell midden [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; The shell mound is on Yeong-do Island [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; The shell mound is in Dongsam-dong, Busan, South Korea [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; The shells were discarded/heaped up by people [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; The people were of the Jeulmun pottery period [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; It is among the oldest Jeulmun middens found so far [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]; The oldest-Jeulmun-midden ranking applies to the southern Korean Peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Shell_Mound_in_Dongsam-dong,_Busan]"}]'::jsonb),
    ('56876b69-7222-4afd-8204-5f1f00bd0725'::uuid, 'card_description', 'Two granite boulders near Øster Velling carry engraved geometric patterns from the Bronze Age — ships, sun discs, and other symbols. The stones were moved 50 metres from their original find spot.', 'In Øster Velling Skov forest, two granite boulders at Mandbjerghøj bear Bronze Age concentric rings and ovals, the same motif found on a gilt belt-hook in the grave of the nearby tumulus.', 'teaser-card-s008:56876b69-7222-4afd-8204-5f1f00bd0725:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f3583d5d46db29efca0881d150f3531e7529059fc832bce9cefe0b4f3c9b5ce9|19ed099530f686e703a60c23796db1f9713a06c7376197fce1b156f355d1d449|19ed099530f686e703a60c23796db1f9713a06c7376197fce1b156f355d1d449', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Øster Velling Skov forest, two granite boulders at Mandbjerghøj bear Bronze Age concentric rings and ovals, the same motif found on a gilt belt-hook in the grave of the nearby tumulus."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Mandbjerghøj [S1]; it lies at Øster Velling Skov forest [S1]; there are two granite boulders [S2]; the boulders bear engraved patterns from the Bronze Age [S2]; the patterns are concentric rings and ovals [S8]; the same motif is found on a gilt belt-hook [S7]; the belt-hook was found in the grave of a tumulus [S6, S7]; the tumulus is nearby [S3, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mandbjerghøj is a rock-art / burial-mound site (petroglyph stones and the remains of a tumulus) in Denmark [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The site lies in Øster Velling Skov forest [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The site is in Jutland, Denmark [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; There are two granite boulders at the site [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The boulders bear Bronze Age engravings [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The motif includes concentric rings [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The motif includes ovals [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; A gilt belt-hook was found in the grave of the tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The belt-hook bore the same motif as the rock carvings [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]; The tumulus (Mandbjerghøj) lies near the stones [SUPPORTED: https://en.wikipedia.org/wiki/Mandbjergh%C3%B8j]"}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'card_description', 'The highest hill in its county at 540 metres, with several Iron Age hillforts. Quarrying destroyed two of the three forts, leaving only Nordy Bank intact.', 'On Brown Clee Hill, the highest hill in Shropshire, Nordy Bank''s ramparts still rise up to three metres, the last survivor of three Iron Age hill forts; two were largely lost to quarrying.', 'teaser-card-s008:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'e1839dc2507f9d6db8840207a2c067d0268b746b485e5af4cf9c8ddafad1bdb3|c8a5972d52a530e7164770359414162d8eea0f95a7590b1265708b5a047084db|c8a5972d52a530e7164770359414162d8eea0f95a7590b1265708b5a047084db', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Brown Clee Hill, the highest hill in Shropshire, Nordy Bank''s ramparts still rise up to three metres, the last survivor of three Iron Age hill forts; two were largely lost to quarrying."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Brown Clee Hill [S1]; Brown Clee Hill is the highest hill in Shropshire [S1]; Nordy Bank is on Brown Clee [S3]; Nordy Bank''s ramparts are up to three metres high, still standing [S5]; Nordy Bank is the last survivor of three hill forts on Brown Clee [S3]; the hill forts are Iron Age [S2, S3, S6]; the other two hill forts were largely lost to quarrying [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Nordy Bank is a hill fort (the central claim: a hill fort on Brown Clee Hill) [SUPPORTED: https://en.wikipedia.org/wiki/Nordy_Bank]; Nordy Bank dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; Brown Clee Hill is the highest hill in Shropshire [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; Nordy Bank''s ramparts still rise up to three metres [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; Nordy Bank is the last survivor of three hill forts on Brown Clee Hill [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; Two of the three hill forts (Abdon Burf and Clee Burf) were largely lost [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; The two lost hill forts were lost to quarrying [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]; The three hill forts of Brown Clee Hill are Iron Age hill forts [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Clee_Hill]"}]'::jsonb),
    ('57ad1380-8a82-42e8-8b2c-03f952ba7bdf'::uuid, 'card_description', 'A 3200 BC passage tomb ringed by 17 satellite tombs, with the largest collection of megalithic art in Europe. Part of the Bru na Boinne World Heritage Site.', 'Above the River Boyne, Knowth''s large passage tomb, ringed by 17 smaller tombs from around 3200 BC, holds the largest assemblage of megalithic art in Europe: over 200 decorated stones.', 'teaser-card-s008:57ad1380-8a82-42e8-8b2c-03f952ba7bdf:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '31da23964e6aacb2893d45a22ac2a0e3b02085bf93be6dfdde0bb3c38b0da3e8|284a30c46447d2bff592e17e7e592d8b786b6659c6a7be502d7e589c68819041|284a30c46447d2bff592e17e7e592d8b786b6659c6a7be502d7e589c68819041', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Above the River Boyne, Knowth''s large passage tomb, ringed by 17 smaller tombs from around 3200 BC, holds the largest assemblage of megalithic art in Europe: over 200 decorated stones."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Knowth [S1]; Knowth is above/overlooking the River Boyne [S1]; Knowth has a large passage tomb [S2]; the passage tomb is surrounded by 17 smaller tombs [S2]; the tombs date from around 3200 BC [S2]; Knowth holds the largest assemblage of megalithic art in Europe [S3]; over 200 decorated stones were found [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Knowth is a passage tomb (central claim: a prehistoric passage tomb in Ireland) [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; Knowth lies above/overlooks the River Boyne [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; The main passage tomb is large [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Knowth]; The large passage tomb is ringed by 17 smaller tombs [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; The tombs date from around 3200 BC [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; Knowth holds the largest assemblage of megalithic art in Europe [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; Knowth has over 200 decorated stones [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]; Knowth''s megalithic art is a very large share of all such art in Western Europe [SUPPORTED: https://en.wikipedia.org/wiki/Knowth]"}]'::jsonb),
    ('57fa22f7-4aec-42ad-a776-19566dba8adc'::uuid, 'card_description', 'The general date of the aqueduct''s construction was long a mystery, although it was thought to have been during the 1st century AD, during the reigns of the Emperors Domitian, Nerva, and Trajan.', 'The Aqueduct of Segovia, its arcade 167 arches long, brought mountain spring water 17 kilometres to fountains and baths until 1973. With no legible inscription, its date was long a mystery.', 'teaser-card-s008:57fa22f7-4aec-42ad-a776-19566dba8adc:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '6eb0935840a62ede49833ec73e231e5716b933c7d6e632c0d905d51da18ff37e|2282a6bc95203b2f68743f374b68c3e19b83cd657eb40277257b0b368a813ea2|2282a6bc95203b2f68743f374b68c3e19b83cd657eb40277257b0b368a813ea2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Aqueduct of Segovia, its arcade 167 arches long, brought mountain spring water 17 kilometres to fountains and baths until 1973. With no legible inscription, its date was long a mystery."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is the Aqueduct of Segovia [S1]; its arcade has 167 arches [S2]; it brought spring water from the mountains [S1]; the water was carried 17 kilometres [S1]; the water went to fountains and baths [S1]; it was in use until 1973 [S1]; the aqueduct has no legible inscription [S3]; its date was long a mystery, i.e. the construction date could not be definitively determined [S3, S4]; the missing inscription is why the date was uncertain [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Aqueduct of Segovia is an aqueduct (central claim: a Roman aqueduct at Segovia, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; Its arcade is 167 arches long [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; The aqueduct carried water 17 kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; The water was spring water from the mountains [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; The water went to fountains [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; The water went to baths [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; The aqueduct was in use until 1973 [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; It has no legible inscription [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; Its date of construction could not be determined and was long a mystery [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]; Because of the missing inscription the date of construction could not be definitively determined [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_Segovia]"}]'::jsonb),
    ('58733868-7f7f-42e3-9d30-2fb9feb7fd05'::uuid, 'card_description', 'Ancient Cretan city-state listed by the Byzantine geographer Hierocles among 22 cities of Crete. Positioned 170 stadia from Hierapytna, it appears in myths tied to Otus and Ephialtes.', NULL, 'teaser-card-s008:58733868-7f7f-42e3-9d30-2fb9feb7fd05:card_description', 'teaser-card-s008 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||126424bf3b510a058d6aa37082bac7c6c60d976817be385e7819fc2df96d0d16', '[{"source": "lane WB run wb-ws-2026-09-27-04: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check could not prove: Biannus was a polis (city-state) of ancient Crete (central claim: an ancient Cretan city); The web check could not prove: Biannus was inland; The web check could not prove: Biannus was an ancient town (polis) of ancient Crete; The web check could not prove: Crete, where Biannus lay, is part of Greece"}]'::jsonb),
    ('58aaa531-5cb7-409c-b0a4-755faf668c9e'::uuid, 'card_description', 'A truncated Ichma-culture pyramid rebuilt over centuries, creating layers of patios, corridors, and enclosures. Each era left its own architectural stamp.', 'In Lima, Huaca Huantinamarca, an Ichma culture site built in at least two phases, was the main seat of a community linked to the collection, transformation and consumption of corn chicha.', 'teaser-card-s008:58aaa531-5cb7-409c-b0a4-755faf668c9e:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '4d85e84e9934a4356c7a351ea3e3f1f874cced24c9d53a8adfd4972ef65d6e6a|234fc54affe3db56c1eba5b0112da44f705698db394cc755ecd38d492e57e106|234fc54affe3db56c1eba5b0112da44f705698db394cc755ecd38d492e57e106', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Lima, Huaca Huantinamarca, an Ichma culture site built in at least two phases, was the main seat of a community linked to the collection, transformation and consumption of corn chicha."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is in Lima [S1]; it is a site of the Ichma culture [S1]; it was built in at least two phases [S2]; it was the main seat of a community [S5]; the community was linked to the collection, transformation and consumption of corn chicha [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Huaca Huantinamarca is an archaeological site (huaca) in Lima, Peru (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; It is a site of the Ichma culture [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; It was built in at least two phases [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; It was the main seat of a community [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; The community was linked to the collection and transformation of corn chicha [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; The community was linked to the consumption of corn chicha [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]; The site lies in Lima (San Miguel District) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huantinamarca]"}]'::jsonb),
    ('58ad6c3e-49ea-4a21-ab5b-2735d30298d1'::uuid, 'card_description', 'Covering 0.84 hectares in Somerset''s Selwood parish, this univallate hillfort retains a bank up to 1.6 m high with a 1.8 m ditch below it. It sits close to the later Hales Castle.', NULL, 'teaser-card-s008:58ad6c3e-49ea-4a21-ab5b-2735d30298d1:card_description', 'teaser-card-s008 (card-clear-failed-after-verify-rewrite): card cleared (failed-after-verify-rewrite)', '||68440ebd5d7f5a4d99e268ebfe447fa1f6b8d26613c097d7478d69179786e06a', '[{"source": "lane WB run wb-ws-2026-09-27-04: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check could not prove: It is now a Scheduled Monument; The web check could not prove: It stood on the Heritage at Risk Register in 2011; No sentence of the description supports the claim: the reader can go and see the site for themselves (the question implies it is open to visit); The tone rules are broken (see the checker''s reasons).; The closing question ''Ready to see it for yourself?'' is a call to action, i.e. marketing copy, not an evocative or mysterious teaser (tone rule 1).; The question implies the hillfort can be visited or is open to the public, and no sentence says anything about access or visiting; drop the question or replace it with a statement the sentences make."}]'::jsonb),
    ('591cee00-2570-4cf4-94d8-a141cf6e9854'::uuid, 'card_description', 'A 3rd-century dam across the Carenque River near Sintra, built to supply Olisipo (Lisbon) with water. Its mortar-bonded masonry survives partially buried beneath a modern road.', 'Built in the 3rd century to serve Olisipo, the Roman Dam of Belas keeps a segment some 15.5 metres long, braced by three buttresses, its channel still crossing the Águas Livres Aqueduct.', 'teaser-card-s008:591cee00-2570-4cf4-94d8-a141cf6e9854:card_description', 'teaser-card-s008 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'c52c24a2a270d5e1075c7d7c6f21d8bd0fe1e1d0f59dcbf5ad2763792f6b606d|af3df77f3fbfe81f47359bc66f57969b9c00d8bd7870820cfe9943ee7b8fee4f|af3df77f3fbfe81f47359bc66f57969b9c00d8bd7870820cfe9943ee7b8fee4f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built in the 3rd century to serve Olisipo, the Roman Dam of Belas keeps a segment some 15.5 metres long, braced by three buttresses, its channel still crossing the Águas Livres Aqueduct."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is the Roman Dam of Belas [S1]; it was built in the 3rd century [S1, S2]; it was built to serve Olisipo [S1]; a surviving segment of the dam is some 15.5 metres long [S3]; the segment is reinforced by three buttresses [S3]; the channel of the structure still crosses the Águas Livres Aqueduct [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Dam of Belas is a Roman dam (barrier) in Belas, Portugal (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]; It was built in the 3rd century [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]; It was built to serve Olisipo [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]; A segment some 15.5 metres long survives [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]; The segment is braced (reinforced) by three buttresses [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]; Its channel still crosses the Aguas Livres Aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Dam_of_Belas]"}]'::jsonb),
    ('5b0b6371-1e89-434a-b125-fcc7349de5db'::uuid, 'card_description', 'Commanding a ridge above the Voghji River, this fortress served as the last capital of the Syunik kingdom before Seljuk forces ended it. Its walls span from the 4th to the 12th century AD.', 'Baghaberd Fortress stands 200 m above the meeting of the Voghjaget and Giratagh rivers, an impregnable stronghold known since the 4th-5th centuries, by tradition built by Patriarch Baghak.', 'teaser-card-s008:5b0b6371-1e89-434a-b125-fcc7349de5db:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7dfd07bd897713f477272a85750bf210af5eba9d78ab47f215d87859c2becda1|f7c8d37645745e74b95727401b9fb6be96224cfbfc676634adc547fd46fac9e7|f7c8d37645745e74b95727401b9fb6be96224cfbfc676634adc547fd46fac9e7', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Baghaberd Fortress stands 200 m above the meeting of the Voghjaget and Giratagh rivers, an impregnable stronghold known since the 4th-5th centuries, by tradition built by Patriarch Baghak."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Baghaberd Fortress [S1]; the fortress stands about 200 m above the riverbed at the confluence of the Voghjaget and Giratagh rivers [S5]; it is an impregnable fortress/stronghold [S3]; it has been known since the 4th-5th centuries [S3]; by tradition it was built by Patriarch Baghak [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Baghaberd is a fortress in Armenia (Syunik) (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]; It stands at the meeting (confluence) of the Voghjaget and Giratagh rivers [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]; It stands 200 m above the river (riverbed) at that meeting [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]; It is an impregnable stronghold [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]; It has been known (as an impregnable fortress) since the 4th-5th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]; By tradition it was built by Patriarch Baghak [SUPPORTED: https://en.wikipedia.org/wiki/Baghaberd]"}]'::jsonb),
    ('5b413fb7-8c04-4923-8b60-cdc126069114'::uuid, 'card_description', '1st-or-2nd-century BC fort in Worcestershire. The name "Berry" derives from burgh — a defensive position; local tradition also calls it "Danes Bury" after a Norse raiding legend.', 'On the outskirts of Birmingham, the Iron Age hill fort of Berry Mound kept a V-shaped ditch 22 ft wide to the south. A third line of ramparts, seen in the 19th century, has left no traces.', 'teaser-card-s008:5b413fb7-8c04-4923-8b60-cdc126069114:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '577d2382a717c3da17f82fede0a324fdae75ac11e7c96ff720a9392d670baafe|de0ec9d62c12b80747d28f8c3c2e7e7a8d56f3983218db3f37901a44e99f2b70|de0ec9d62c12b80747d28f8c3c2e7e7a8d56f3983218db3f37901a44e99f2b70', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the outskirts of Birmingham, the Iron Age hill fort of Berry Mound kept a V-shaped ditch 22 ft wide to the south. A third line of ramparts, seen in the 19th century, has left no traces."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Berry Mound [S1]; it is on the outskirts of Birmingham [S1]; it is an Iron Age hill fort [S1]; it had a V-shaped ditch to the south [S3]; the southern ditch was 22 ft wide [S3]; 19th century observers recorded a third line of ramparts [S4]; no traces of the third line remain [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Berry Mound is a hill fort (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; It lies on the outskirts of Birmingham [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; It is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; It had a V-shaped ditch to the south [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; The southern ditch was 22 ft wide [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; A third line of ramparts was seen (recorded) by observers in the 19th century [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]; The third line of ramparts has left no traces [SUPPORTED: https://en.wikipedia.org/wiki/Berry_Mound]"}]'::jsonb),
    ('5b4e478e-a052-46d9-b892-c3894bd8c3ae'::uuid, 'card_description', 'A strategic Roman city fought over during the Samnite and Punic wars. Oscan tombstones at the site confirm pre-Roman Italic inhabitants.', 'In the picturesque Bosco d''Acerra forest lie the ruins of Suessula, where traces of the theater may still be seen and Oscan tombs were excavated, with important finds of vases and bronzes.', 'teaser-card-s008:5b4e478e-a052-46d9-b892-c3894bd8c3ae:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8b1e0ea3c6c188cd4642340c78e3821be598fd789d78dcd982acfcb33ee3c7d6|e2b08ef921ceb786c16dfec4e0487a590b06341bea3c8f59dd6732eda62058ce|e2b08ef921ceb786c16dfec4e0487a590b06341bea3c8f59dd6732eda62058ce', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-010", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the picturesque Bosco d''Acerra forest lie the ruins of Suessula, where traces of the theater may still be seen and Oscan tombs were excavated, with important finds of vases and bronzes."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is Suessula [S1]; the ruins lie in the Bosco d''Acerra forest [S4]; the forest is picturesque [S4]; traces of the theater may still be seen [S5]; Oscan tombs were excavated there [S6]; important finds of vases were made [S6]; important finds of bronzes were made [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Suessula was an ancient city (now ruins) in Campania, Italy (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; The ruins of Suessula lie within the Bosco d''Acerra forest [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; The Bosco d''Acerra is a picturesque forest [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; Traces of the theater may still be seen [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; Oscan tombs were excavated at Suessula [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; Important finds of vases and bronzes were made [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]; Suessula is now a vanished city whose ruins/archaeological site survive [SUPPORTED: https://en.wikipedia.org/wiki/Suessula]"}]'::jsonb),
    ('5beb80c3-7968-4097-b2b3-a699f276ca88'::uuid, 'card_description', 'Capital of the Illyrian Daorsi, with cyclopean walls of massive stone blocks around an acropolis. The Daorsi minted their own coins — a sign of serious political power.', 'Near Stolac, cyclopean walls of huge stone blocks surrounded Daorson, capital of the Illyrian Daorsi. Its most valuable find: a bronze helmet decorated with a series of mythological figures.', 'teaser-card-s008:5beb80c3-7968-4097-b2b3-a699f276ca88:card_description', 'teaser-card-s008 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '6ac2a36d8197b80c04a627fb4eb8e4a67376ce5583eda7ede95591d83f259c06|ee378388ea6f41433f27a559ba2ef0c4ebdcf391eaf46dbfd284a8214e4246a8|ee378388ea6f41433f27a559ba2ef0c4ebdcf391eaf46dbfd284a8214e4246a8', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near Stolac, cyclopean walls of huge stone blocks surrounded Daorson, capital of the Illyrian Daorsi. Its most valuable find: a bronze helmet decorated with a series of mythological figures."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies near Stolac [S3]; cyclopean walls of huge stone blocks surrounded Daorson [S4]; Daorson was the capital of the Illyrian Daorsi [S1]; the most valuable find is a bronze helmet [S6]; the helmet is decorated with a series of mythological figures [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Daorson was an ancient town built around a central fort or acropolis (a fortified hill-fort settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]; Daorson is located near Stolac, Bosnia and Herzegovina [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]; Cyclopean walls surrounded Daorson [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]; The walls were made of huge stone blocks [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]; Daorson was the capital of the Illyrian Daorsi [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]; Its most valuable find is a bronze helmet decorated with a series of mythological figures [SUPPORTED: https://en.wikipedia.org/wiki/Daorson]"}]'::jsonb),
    ('5c4b2afd-f915-4625-a841-790460fddef5'::uuid, 'card_description', 'Archaeology shows that around 580-560 BC the city was completely rebuilt after an unknown event destroyed it.', 'On Sicily''s north coast, the Doric Tempio della Vittoria of Himera commemorates the defeat of the Carthaginians, whose expedition of 409 BC brought the city''s prosperity to an abrupt end.', 'teaser-card-s008:5c4b2afd-f915-4625-a841-790460fddef5:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '968ea94dc00b674a938e7b853d929f95d5e4c08c40ed887c879a7e5435977164|edc2a5f7a85b73ee31366111ba81b284b83b3a05f6875fcf2931058e764f9c4c|edc2a5f7a85b73ee31366111ba81b284b83b3a05f6875fcf2931058e764f9c4c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Sicily''s north coast, the Doric Tempio della Vittoria of Himera commemorates the defeat of the Carthaginians, whose expedition of 409 BC brought the city''s prosperity to an abrupt end."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Himera lies on Sicily''s north coast [S1]; the Tempio della Vittoria belongs to Himera (its lower city) [S5]; the Tempio della Vittoria is a Doric structure [S5]; the temple commemorates the defeat of the Carthaginians [S5]; the Carthaginians mounted an expedition against Sicily in 409 BC [S4]; that expedition brought the city''s prosperity to an abrupt end [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Himera was an ancient Greek city on the north coast of Sicily [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; The Tempio della Vittoria (Temple of Victory) is a monument of the lower city of Himera [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; The Tempio della Vittoria of Himera is a Doric temple [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; The Tempio della Vittoria commemorates the defeat of the Carthaginians [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; The Carthaginians were defeated at Himera (Battle of Himera, 480 BC) [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; A Carthaginian expedition of 409 BC brought Himera''s prosperity to an abrupt end [SUPPORTED: https://en.wikipedia.org/wiki/Himera]; The 409 BC Carthaginian expedition destroyed Himera, ending its existence as a city [SUPPORTED: https://en.wikipedia.org/wiki/Himera]"}]'::jsonb),
    ('5cd47e05-c322-4510-b40f-c1f75072c147'::uuid, 'card_description', '5400 BC Sumerian city — believed the earliest in southern Mesopotamia. Buildings of mud brick were stacked atop one another as temples grew upward and the village expanded outward.', 'Eridu was founded circa 5400 BC on a virgin sand dune, then close to the Persian Gulf. Beneath the unfinished ziggurat of Amar-Sin lie eighteen superimposed mudbrick temples.', 'teaser-card-s008:5cd47e05-c322-4510-b40f-c1f75072c147:card_description', 'teaser-card-s008 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '3349e3e7987ddcf581bba37349e8cf623009afa38902f89938fca01942e5c252|b4bdfb42a720237cd787be6dded866b7a303d2ef811d2e3a04b6274edf743719|b4bdfb42a720237cd787be6dded866b7a303d2ef811d2e3a04b6274edf743719', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Eridu was founded circa 5400 BC on a virgin sand dune, then close to the Persian Gulf. Beneath the unfinished ziggurat of Amar-Sin lie eighteen superimposed mudbrick temples."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Eridu was founded circa 5400 BC [S5]; it was founded on a virgin sand dune [S6]; at that time the site was close to the Persian Gulf [S5]; the ziggurat of Amar-Sin at the site is unfinished [S7]; eighteen superimposed mudbrick temples lie beneath that ziggurat [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Eridu was an ancient Sumerian city (a settlement built around temples) at Tell Abu Shahrain in southern Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]; Eridu was founded circa 5400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]; At its founding Eridu lay close to the Persian Gulf [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]; Eridu was founded on a virgin sand dune [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]; Eighteen superimposed mudbrick temples lie at Eridu [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]; The eighteen temples lie beneath the unfinished ziggurat of Amar-Sin [SUPPORTED: https://en.wikipedia.org/wiki/Eridu]"}]'::jsonb),
    ('5d8ab96d-45d0-47dd-8e05-8202baf131c1'::uuid, 'card_description', 'A source critical review and 25 new radiocarbon dates demonstrated that the Carrowmore monuments are shown to have spanned the era circa 3750 BC to circa 3000 BC.', 'West of Sligo, satellite tombs surround the cairn of Listoghil at Carrowmore, erected circa 3500 BC with a box-like chamber, in a ritual landscape dominated by the mountain of Knocknarea.', 'teaser-card-s008:5d8ab96d-45d0-47dd-8e05-8202baf131c1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '83dd4663daecceb60ff50475a42b1cf434f3566a970e90a4fef7b109dd93f13d|24068518ea3f834ab480165c320d3ab10b7fbc639a901d8a643aa14852c6993f|24068518ea3f834ab480165c320d3ab10b7fbc639a901d8a643aa14852c6993f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "West of Sligo, satellite tombs surround the cairn of Listoghil at Carrowmore, erected circa 3500 BC with a box-like chamber, in a ritual landscape dominated by the mountain of Knocknarea."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Carrowmore lies west of Sligo [S1]; satellite tombs surround the cairn of Listoghil [S4]; Listoghil is at Carrowmore [S3, S4]; Listoghil was erected circa 3500 BC [S5]; Listoghil has a box-like chamber [S5]; Carrowmore lies in a ritual landscape [S3]; that landscape is dominated by the mountain of Knocknarea [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Carrowmore is a group of megalithic monuments west of Sligo, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; The Carrowmore monuments are tombs [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; Satellite tombs surround the largest monument at Carrowmore [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; The central monument is the cairn called Listoghil [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; The Listoghil cairn was erected circa 3500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; Listoghil has a box-like chamber [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; Carrowmore is the heart of an ancient ritual landscape [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]; The ritual landscape is dominated by the mountain of Knocknarea [SUPPORTED: https://en.wikipedia.org/wiki/Carrowmore]"}]'::jsonb),
    ('5e384859-dede-47ed-8d4e-0509d425234e'::uuid, 'card_description', 'Augustan-era Ionic octostyle temple in the Agora''s southeast corner, assembled from architectural fragments stripped from the Temple of Athena at Sounion in Attica.', 'Built from fragments of the Temple of Athena at Sounion, the Southeast Temple of the Ancient Agora of Athens was the last of several itinerant temples. Its god or hero is unknown.', 'teaser-card-s008:5e384859-dede-47ed-8d4e-0509d425234e:card_description', 'teaser-card-s008 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'de6f29765de627d04ad52706b60180a432580d96d7a5ddd9d637bb9796ed74ea|c286b5cb6d49b9df99118e5a78a0ab361351c82ef14c7954b229be7834749110|c286b5cb6d49b9df99118e5a78a0ab361351c82ef14c7954b229be7834749110', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built from fragments of the Temple of Athena at Sounion, the Southeast Temple of the Ancient Agora of Athens was the last of several itinerant temples. Its god or hero is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple was built from fragments of the Temple of Athena at Sounion [S3]; the Southeast Temple was the last of several itinerant temples [S4]; the god or hero it was dedicated to is unknown [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Southeast Temple is a temple in the southeast corner of the Ancient Agora of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Southeast_Temple]; The temple''s architectural fragments originally belonged to the Temple of Athena at Sounion [SUPPORTED: https://en.wikipedia.org/wiki/Southeast_Temple]; The Sounion fragments were re-used (spoliated) to build the temple in the Agora [SUPPORTED: https://en.wikipedia.org/wiki/Southeast_Temple]; It was the last of several itinerant temples [SUPPORTED: https://en.wikipedia.org/wiki/Southeast_Temple]; The god or hero to whom the temple was dedicated is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Southeast_Temple]"}]'::jsonb),
    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'card_description', 'Karstic hills with fossil deposits and stone tools of Western Europe’s earliest known hominins. Ongoing excavations have repeatedly reshaped understanding of when humans first spread across Europe.', 'The karstic hills of the Atapuerca Mountains hold fossils and stone tools attributed to the earliest known hominin residents in Western Europe, and a new genus of red-toothed shrew.', 'teaser-card-s008:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:card_description', 'teaser-card-s008 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'ae546d56d8168f04c11e54ae934a1794ff86371351a5cb2c99f25c856faa774d|15b257ffa2a995095afa2b3853eecb2de79ef7b834ad72ad786e4085f659e2d9|15b257ffa2a995095afa2b3853eecb2de79ef7b834ad72ad786e4085f659e2d9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The karstic hills of the Atapuerca Mountains hold fossils and stone tools attributed to the earliest known hominin residents in Western Europe, and a new genus of red-toothed shrew."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Atapuerca Mountains are karstic hills [S1, S3]; fossils and stone tools have been found there [S2]; the fossils and stone tools are attributed to the earliest known hominin residents in Western Europe [S2]; a new genus of red-toothed shrew was identified from the site''s cave layers [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Atapuerca Mountains are a karstic hill formation (near the village of Atapuerca, province of Burgos) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Atapuerca_Mountains]; The karstic hills hold fossils (rich fossil deposits) [SUPPORTED: https://en.wikipedia.org/wiki/Atapuerca_Mountains]; The hills hold stone tools (stone tool assemblages) [SUPPORTED: https://en.wikipedia.org/wiki/Atapuerca_Mountains]; The fossils and stone tools are attributed to the earliest known hominin residents in Western Europe [SUPPORTED: https://en.wikipedia.org/wiki/Atapuerca_Mountains]; A new genus of red-toothed shrew was identified from the Atapuerca Mountains (Gran Dolina cave) [SUPPORTED: https://en.wikipedia.org/wiki/Atapuerca_Mountains]"}]'::jsonb),
    ('5fc3dde6-5284-41ba-af51-d91420bd0299'::uuid, 'card_description', 'Built around 19 BC, the Pont du Gard carries a Roman aqueduct 49 metres above the Gardon river on three tiers of limestone arches. The channel conveyed water over 50 km to Nemausus.', 'Three tiers of shelly limestone arches rise 48.8 m at the Pont du Gard, a Roman aqueduct bridge so precise its gradient averages 1 cm in 182.4 m. Later it served as a toll bridge.', 'teaser-card-s008:5fc3dde6-5284-41ba-af51-d91420bd0299:card_description', 'teaser-card-s008 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '76f59ac473c30bd42c5170572f74042db0cb1dc444839f673ca155556a4a3065|ea89ebb2935c4d7231e5fd42fe265e6b9eeffe0a78e6bf954ca7e39dde8b981f|ea89ebb2935c4d7231e5fd42fe265e6b9eeffe0a78e6bf954ca7e39dde8b981f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Three tiers of shelly limestone arches rise 48.8 m at the Pont du Gard, a Roman aqueduct bridge so precise its gradient averages 1 cm in 182.4 m. Later it served as a toll bridge."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the bridge has three tiers of arches [S2]; the arches are made of shelly limestone [S2]; the structure stands 48.8 m high [S2]; the Pont du Gard is a Roman aqueduct bridge [S1]; its precise construction gives an average gradient of 1 cm in 182.4 m [S3]; later it served as a toll bridge [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Pont du Gard is a Roman aqueduct bridge (in southern France) [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]; The bridge has three tiers of arches [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]; The arches are made of shelly limestone [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]; The bridge rises 48.8 m [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]; The precise construction allowed an average gradient of 1 cm in 182.4 m [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]; Later the Pont du Gard served as a toll bridge [SUPPORTED: https://en.wikipedia.org/wiki/Pont_du_Gard]"}]'::jsonb),
    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'card_description', 'The site has been occupied by humans since the late Bronze Age and includes the remains of a Romano-Celtic Temple.', 'Off Somerset, the promontory of Brean Down bears traces of an Iron Age hill fort, prehistoric barrows and a Romano-Celtic Temple. Quarrying there turned up gold coins of Augustus and Nero.', 'teaser-card-s008:611a3218-4df9-4018-8d46-c1e731f04b2a:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ad72904c97dbe46a7910c7007afdc7ab965599cef2288e987dddd2028d512453|226e2dbb8d078e4ffae3cc35b2821dcfd061d1b11b97efeab9956cc56ec27796|226e2dbb8d078e4ffae3cc35b2821dcfd061d1b11b97efeab9956cc56ec27796', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Off Somerset, the promontory of Brean Down bears traces of an Iron Age hill fort, prehistoric barrows and a Romano-Celtic Temple. Quarrying there turned up gold coins of Augustus and Nero."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Brean Down is a promontory off the coast of Somerset [S1]; it bears traces of an Iron Age hill fort [S4]; it bears traces of prehistoric barrows [S4]; it bears remains of a Romano-Celtic Temple [S2, S5]; quarrying at the site turned up gold coins of Augustus and Nero [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Brean Down is a promontory off the coast of Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Brean_Down]; Brean Down bears evidence of an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Brean_Down]; Brean Down bears prehistoric barrows [SUPPORTED: https://en.wikipedia.org/wiki/Brean_Down]; Brean Down has the remains of a Romano-Celtic Temple [SUPPORTED: https://en.wikipedia.org/wiki/Brean_Down]; Quarrying at Brean Down turned up gold coins of Augustus and Nero [SUPPORTED: https://en.wikipedia.org/wiki/Brean_Down]"}]'::jsonb),
    ('61c3203a-1363-412c-8977-a32cbb67b3cc'::uuid, 'card_description', 'A 4th-century AD tomb famous for exceptional wall paintings — among the finest examples of late antique art anywhere in the Balkans.', 'Found by chance in 1942, the Roman Tomb of Silistra is the best-preserved architectural monument of Roman Durostorum: a single burial chamber beneath a semi-cylindrical brick vault.', 'teaser-card-s008:61c3203a-1363-412c-8977-a32cbb67b3cc:card_description', 'teaser-card-s008 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '9d7348a1c85e788b5c63089255062a2dfaf166f757404ca8718b5a65ecda9b77|8aafb708891d673631d060a2eea8d2b1338815b2433eb064532ddc4625486282|8aafb708891d673631d060a2eea8d2b1338815b2433eb064532ddc4625486282', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Found by chance in 1942, the Roman Tomb of Silistra is the best-preserved architectural monument of Roman Durostorum: a single burial chamber beneath a semi-cylindrical brick vault."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the tomb was found by chance in 1942 [S3]; it is the best-preserved architectural monument of Roman Durostorum [S2]; it has a single burial chamber [S4]; it has a semi-cylindrical brick vault [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Tomb of Silistra is an ancient Roman burial tomb in the town of Silistra (Bulgaria), in Roman Durostorum [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Tomb_(Silistra)]; The tomb was found by chance in 1942 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Tomb_(Silistra)]; It is the best-preserved architectural monument of Roman Durostorum [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Tomb_(Silistra)]; The tomb has a single burial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Tomb_(Silistra)]; The chamber lies beneath a semi-cylindrical brick vault [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Tomb_(Silistra)]"}]'::jsonb),
    ('61d7e44d-2cf4-4b54-84e6-7f1bc9cf911e'::uuid, 'card_description', 'Owned by two wealthy freedmen -- former slaves turned rich merchants. Wall frescoes completed after the 62 AD earthquake are among Pompeii''s best preserved.', 'Preserved by the eruption of Vesuvius in 79 AD, the House of the Vettii, owned by two successful freedmen, still shows almost all its wall frescos, completed after the earthquake of 62 AD.', 'teaser-card-s008:61d7e44d-2cf4-4b54-84e6-7f1bc9cf911e:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a4252b042773b20bb64920a71d3114a56fb342083fac1a373daafe62a050e193|0f7f1beba0b40f7ddbd47e62fb8bbe4a420b6b33eacca49cbb324e2107540643|0f7f1beba0b40f7ddbd47e62fb8bbe4a420b6b33eacca49cbb324e2107540643', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Preserved by the eruption of Vesuvius in 79 AD, the House of the Vettii, owned by two successful freedmen, still shows almost all its wall frescos, completed after the earthquake of 62 AD."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the house lies in Pompeii, preserved by the eruption of Vesuvius in 79 AD [S1]; the house was owned by two successful freedmen [S2]; almost all its wall frescos are still preserved [S3]; the frescos were completed after the earthquake of 62 AD [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The House of the Vettii is a domus (Roman house) in the Roman town of Pompeii [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Vettii]; Pompeii and the house were preserved by the eruption of Vesuvius in 79 AD [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Vettii]; The house was owned by two successful freedmen [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Vettii]; The house still shows almost all of its wall frescos [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Vettii]; The wall frescos were completed after the earthquake of 62 AD [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Vettii]"}]'::jsonb),
    ('626e8712-71b4-48ac-9b58-8440bade0fcc'::uuid, 'card_description', '3rd–4th century AD Mithraic shrine in Roman Savaria. Two stone altars with relief scenes from the life of Mithras survive, alongside fragments of coffered ceiling paintings currently being restored.', 'Found in 2008 during building works for a shopping center in Szombathely, the Savaria Mithraeum held two stone altars carved with scenes from the life of Mithras, under a coffered ceiling.', 'teaser-card-s008:626e8712-71b4-48ac-9b58-8440bade0fcc:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '28334a97d93bf388e847529ccf2bed6ccfe9ccfd11feeaae3001d641c1147b81|b01afd9df66a42df152c1e4f37441ac77b89007c1d2870232c5c6a24e9a7089d|b01afd9df66a42df152c1e4f37441ac77b89007c1d2870232c5c6a24e9a7089d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Found in 2008 during building works for a shopping center in Szombathely, the Savaria Mithraeum held two stone altars carved with scenes from the life of Mithras, under a coffered ceiling."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Mithraeum was found in 2008 [S1, S3]; it was found during building works for a shopping center [S3]; it is in Szombathely [S1]; it held two stone altars [S4]; the altars were decorated in relief with scenes from the life of Mithras [S4]; the ceiling was coffered [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Savaria Mithraeum is a shrine of Mithras (a mithraeum) in the Roman town of Savaria, in Szombathely, Hungary [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]; It was found in 2008 [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]; It was found during building works for a shopping center [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]; The mithraeum held two stone altars [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]; The altars were carved with scenes from the life of Mithras [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]; The mithraeum had a coffered ceiling [SUPPORTED: https://en.wikipedia.org/wiki/Savaria_Mithraeum]"}]'::jsonb),
    ('627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef'::uuid, 'card_description', 'Indus Valley city occupied 4000–1700 BC, the civilisation''s centre for manufacturing carnelian beads. Three low mounds conceal a single 7-hectare settlement 130 kilometres south of Mohenjo-daro.', 'Investigated in 1931 by N. G. Majumdar, Chanhudaro shows evidence of shell working. Bangles and ladles were made here, and it is considered one of the centres where seals were manufactured.', 'teaser-card-s008:627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'edf741ff21695d2a936dfa0b424ef864c053119fa58c7a58119b7962ae687d11|0e992ff0d059a36863809c08a16c88a5a4666e962f77c73e07f6bf02c060a678|0e992ff0d059a36863809c08a16c88a5a4666e962f77c73e07f6bf02c060a678', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Investigated in 1931 by N. G. Majumdar, Chanhudaro shows evidence of shell working. Bangles and ladles were made here, and it is considered one of the centres where seals were manufactured."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chanhudaro was investigated in 1931 [S2]; the investigator was N. G. Majumdar [S2]; Chanhudaro shows evidence of shell working [S3]; bangles and ladles were made at the site [S3]; it is considered one of the centres where seals were manufactured [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chanhudaro is an archaeological site of the Indus Valley civilization in Sindh, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]; Chanhudaro lies in Pakistan (Sindh) [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]; Chanhudaro was investigated in 1931 by N. G. Majumdar [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]; Chanhudaro shows evidence of shell working [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]; Bangles and ladles were made at Chanhudaro [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]; Chanhudaro is considered one of the centres where seals were manufactured [SUPPORTED: https://en.wikipedia.org/wiki/Chanhudaro]"}]'::jsonb),
    ('6290bb50-27f9-412e-86d8-0c9faf98dfc1'::uuid, 'card_description', 'Stone carvings of moose and other animals covering about 20 sq m. The largest figure spans 90 cm, etched by Stone Age hunters millennia ago.', 'Moose carved in deep, wide strokes and repainted mark the Rock Carvings at Møllerstufossen, where the river Etna, approximately 10 metres away, nearly floods the site in spring.', 'teaser-card-s008:6290bb50-27f9-412e-86d8-0c9faf98dfc1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'ee04f265f662b4ebb6813d0334170c91a7b5a12b375769e56f681b1766628011|4f77b2b9e3bcd112b1de275b3e1f0258df54bed14e9acec3537a43f5064c68e4|4f77b2b9e3bcd112b1de275b3e1f0258df54bed14e9acec3537a43f5064c68e4', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Moose carved in deep, wide strokes and repainted mark the Rock Carvings at Møllerstufossen, where the river Etna, approximately 10 metres away, nearly floods the site in spring."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the carvings show moose [S2]; the figures are carved in deep, wide strokes [S5]; the figures have been repainted [S5]; the river Etna runs approximately 10 metres from the site [S6]; in spring the river nearly floods the site [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Rock Carvings at Møllerstufossen are petroglyphs (rock carvings) in Nordre Land Municipality, Norway [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]; The carvings depict moose [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]; The moose are carved in deep, wide strokes [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]; The carvings have been repainted [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]; The river Etna runs approximately 10 metres from the site [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]; The river nearly floods the site in spring [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_M%C3%B8llerstufossen]"}]'::jsonb),
    ('6290ca43-4ceb-458c-a59c-cbe0053be3c1'::uuid, 'card_description', 'At 340 meters on an eastern Quantock spur, this fort and its associated round barrow overlook the Bristol Channel. Both are on the Heritage at Risk Register due to vehicle damage and erosion.', 'At 340 metres on a spur of the Quantock Hills, the Iron Age hill fort of Dowsborough Camp has views north to the Bristol Channel and east over the valley of the River Parrett.', 'teaser-card-s008:6290ca43-4ceb-458c-a59c-cbe0053be3c1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '358266318aec6b1dd3bc8f1b4c07ade8e108315198106ba2efc40046c3279a30|b0efde1d68f02bd5c836fa03e2402a7770534efd036f930789255f5146798244|b0efde1d68f02bd5c836fa03e2402a7770534efd036f930789255f5146798244', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At 340 metres on a spur of the Quantock Hills, the Iron Age hill fort of Dowsborough Camp has views north to the Bristol Channel and east over the valley of the River Parrett."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is at a height of 340 metres [S3]; it lies on a spur of the Quantock Hills [S1, S3]; Dowsborough Camp is an Iron Age hill fort [S1]; it has views north to the Bristol Channel [S3]; it has views east over the valley of the River Parrett [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dowsborough Camp is a hill fort on the Quantock Hills (Somerset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]; The site lies at a height of 340 metres [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]; The site lies on a spur of the Quantock Hills [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]; It has views north to the Bristol Channel [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]; It has views east over the valley of the River Parrett [SUPPORTED: https://en.wikipedia.org/wiki/Dowsborough]"}]'::jsonb),
    ('629670bb-a4ec-4a5a-97a5-7623f86f46d8'::uuid, 'card_description', 'A 5th-century BC healing sanctuary where the sick brought offerings to the god Asclepius. Marble reliefs of healed body parts — legs, eyes, hands — lined the walls as thank-you gifts.', 'On the southern escarpment of the Acropolis hill, visitors to the Asclepieion of Athens spent the night in the Doric stoa, hoping to see the god in their dreams and be healed by him.', 'teaser-card-s008:629670bb-a4ec-4a5a-97a5-7623f86f46d8:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '917d04a1e92ee24d04c9d72204f380b9145830dfcc64b97c9fbf433844fc0108|3ea9fcdb83c0cee3a6464e9efe23bdfb9615789cbeb271524f21b3db7f7aded6|3ea9fcdb83c0cee3a6464e9efe23bdfb9615789cbeb271524f21b3db7f7aded6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-011", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the southern escarpment of the Acropolis hill, visitors to the Asclepieion of Athens spent the night in the Doric stoa, hoping to see the god in their dreams and be healed by him."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Asclepieion lies on the southern escarpment of the Acropolis hill [S1]; visitors spent the night in the Doric stoa [S5]; they hoped to see the god in their dreams [S5]; they hoped to be healed by the god [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Asclepieion of Athens is an ancient Greek temple/sanctuary of Asclepius in Athens [SUPPORTED: https://en.wikipedia.org/wiki/Asclepieion_of_Athens]; It lies on the southern escarpment of the Acropolis hill [SUPPORTED: https://en.wikipedia.org/wiki/Asclepieion_of_Athens]; Visitors seeking healing spent the night in the Doric stoa [SUPPORTED: https://en.wikipedia.org/wiki/Asclepieion_of_Athens]; They hoped to see the god in their dreams [SUPPORTED: https://en.wikipedia.org/wiki/Asclepieion_of_Athens]; They hoped to be healed by the god [SUPPORTED: https://en.wikipedia.org/wiki/Asclepieion_of_Athens]"}]'::jsonb),
    ('62e7aef7-f914-4080-ae06-b4c347600d6d'::uuid, 'card_description', 'Built entirely of stone blocks in 238 AD, this oval amphitheatre seats 35,000 — the third-largest in the Roman world. Constructed on flat ground with no earthen banking, it stands almost fully intact.', 'On flat ground stands El Jem Amphitheatre, an oval whose axes measure 148 metres and 122 metres. Exceptionally well conserved, it is one of the biggest amphitheatres in the world.', 'teaser-card-s008:62e7aef7-f914-4080-ae06-b4c347600d6d:card_description', 'teaser-card-s008 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '1be778642619b42fb0de6b063067cb455a26778d17d97b3382af6dd25134050f|f1a4a967d7137bf456d4e0faf9340b63e639c4959cd2089340787fb7dcc7282a|f1a4a967d7137bf456d4e0faf9340b63e639c4959cd2089340787fb7dcc7282a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On flat ground stands El Jem Amphitheatre, an oval whose axes measure 148 metres and 122 metres. Exceptionally well conserved, it is one of the biggest amphitheatres in the world."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the amphitheatre stands on flat ground [S6, W1]; it is an oval [S1]; its major and minor axes measure 148 metres and 122 metres [S5]; it is exceptionally well conserved [S6]; it is one of the biggest amphitheatres in the world [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "El Jem Amphitheatre is an amphitheatre in El Djem, Tunisia [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]; The amphitheatre is oval [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]; The amphitheatre stands on flat ground [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]; Its axes measure 148 metres (major) and 122 metres (minor) [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]; The amphitheatre is exceptionally well conserved [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]; It is one of the biggest amphitheatres in the world [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_El_Djem]"}, {"source": "web fact W1", "url": "https://fr.wikipedia.org/wiki/Amphith%C3%A9%C3%A2tre_d%27El_Jem", "quote": "plus important, construit sur un terrain plat"}]'::jsonb),
    ('6313cd62-456d-4a85-8782-57613c7fc0e1'::uuid, 'card_description', 'The Great Pyramid served as the tomb of Egyptian Pharaoh Khufu, who ruled during the Fourth Dynasty of the Old Kingdom.', 'Tomb of Khufu, the Great Pyramid of Giza rose circa 2600 BC from an estimated 2.3 million quarried blocks. East of it, three boat-shaped pits are large enough to have held complete boats.', 'teaser-card-s008:6313cd62-456d-4a85-8782-57613c7fc0e1:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '848963fa4190c00a3d85a1daa1098c8df34bb4f876a6ed2db40f0fb32fe61e97|12a5345d328761f16edf87398cfd2ec8e859a6e472c185b1ae1d975eda07c2ee|12a5345d328761f16edf87398cfd2ec8e859a6e472c185b1ae1d975eda07c2ee', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tomb of Khufu, the Great Pyramid of Giza rose circa 2600 BC from an estimated 2.3 million quarried blocks. East of it, three boat-shaped pits are large enough to have held complete boats."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Great Pyramid of Giza served as the tomb of Khufu [S3]; it was built circa 2600 BC [S4]; it was built from an estimated 2.3 million quarried blocks [S5]; three boat-shaped pits lie east of the pyramid [W1]; the pits are large enough to have held complete boats [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Great Pyramid of Giza is the tomb of Khufu, in Giza, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]; The Great Pyramid is located in Giza, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]; It was built circa 2600 BC [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]; It was built from an estimated 2.3 million quarried blocks [SUPPORTED: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]; Three boat-shaped pits lie east of the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]; The pits are large enough to have held complete boats [SUPPORTED: https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza]"}, {"source": "web fact W1", "url": "https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza", "quote": "Three boat-shaped pits are located east of the pyramid. They are large enough in size and shape to have held complete boats"}]'::jsonb),
    ('643c0a08-cde9-4a47-a05c-a1f72227f772'::uuid, 'card_description', 'Substructures that once held up Emperor Diocletian''s private apartments, built in the 4th century AD. Among the best-preserved Roman substructures in the world.', 'The Cellars of Diocletian''s Palace once held up the Emperor''s private apartments and stored the Palace''s wine. Research here has revealed structures two centuries older than the palace.', 'teaser-card-s008:643c0a08-cde9-4a47-a05c-a1f72227f772:card_description', 'teaser-card-s008 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2374f8800ee3bca7ecc9a8bf1b73621b2b3680b9eae3b0884ef99898aa2a7160|e8f289381804f846181c49fc4c954539cd90955a767ace9c01dbbbc3283a5639|e8f289381804f846181c49fc4c954539cd90955a767ace9c01dbbbc3283a5639', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Cellars of Diocletian''s Palace once held up the Emperor''s private apartments and stored the Palace''s wine. Research here has revealed structures two centuries older than the palace."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the cellars once held up the Emperor''s private apartments [S1]; the cellars stored the Palace''s wine [S3]; research at the site has revealed structures [S2]; those structures predate the palace by two centuries [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Cellars of Diocletian''s Palace are a set of substructures at the southern end of Diocletian''s Palace [SUPPORTED: https://en.wikipedia.org/wiki/Cellars_of_Diocletian%27s_Palace]; The palace and its cellars are in Split, Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Diocletian%27s_Palace]; The cellars once held up the Emperor''s private apartments [SUPPORTED: https://en.wikipedia.org/wiki/Cellars_of_Diocletian%27s_Palace]; The cellars stored the Palace''s wine [SUPPORTED: https://en.wikipedia.org/wiki/Cellars_of_Diocletian%27s_Palace]; Research in the cellars has revealed structures two centuries older than the palace [SUPPORTED: https://en.wikipedia.org/wiki/Cellars_of_Diocletian%27s_Palace]"}]'::jsonb),
    ('648d388d-8532-4605-9345-1b656640455e'::uuid, 'card_description', 'Fleam Dyke is a linear earthwork between Fulbourn and Balsham in Cambridgeshire, initiated some time between AD 330 and AD 510.', 'Fleam Dyke, a linear earthwork between Fulbourn and Balsham, gave up Anglo-Saxon weapons and burials. In 1991, radiocarbon dating showed it was built in several phases.', 'teaser-card-s008:648d388d-8532-4605-9345-1b656640455e:card_description', 'teaser-card-s008 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '79554b03d76dcdb3219842e5f32ad025e9d1086f5065d19eee06fe50024afa10|08a53042a31f921a19c17f825d24ae63aa78b7088b77c6b327d57b1910619106|08a53042a31f921a19c17f825d24ae63aa78b7088b77c6b327d57b1910619106', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Fleam Dyke, a linear earthwork between Fulbourn and Balsham, gave up Anglo-Saxon weapons and burials. In 1991, radiocarbon dating showed it was built in several phases."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Fleam Dyke is a linear earthwork [S1]; it lies between Fulbourn and Balsham [S1, S2]; Anglo-Saxon weapons were found there [S5]; Anglo-Saxon burials were found there [S5]; in 1991 radiocarbon dating showed it was built in several phases [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Fleam Dyke is a linear earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]; The earthwork lies between Fulbourn and Balsham (Cambridgeshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]; The dyke gave up Anglo-Saxon weapons [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]; The dyke gave up Anglo-Saxon burials [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]; An excavation in 1991 dated the dyke by radiocarbon dating [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]; The dyke was built in several phases [SUPPORTED: https://en.wikipedia.org/wiki/Fleam_Dyke]"}]'::jsonb),
    ('6493afc6-9665-440c-90ea-1e7d9fc28e6b'::uuid, 'card_description', 'Founded as early as the 8th century BC at Gadir for Phoenician Melqart, later rededicated under Rome. Hannibal, Scipio Africanus, and Caesar each visited before launching their greatest campaigns.', 'On the southern outskirts of Gadir-Gades, perhaps as early as the 8th century BC, the Temple of Hercules Gaditanus was dedicated to Melqart, then Hercules. Hannibal and Caesar paid respect.', 'teaser-card-s008:6493afc6-9665-440c-90ea-1e7d9fc28e6b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '909b8d52d0a31116bc5316ab6c7e5a05e7ad7dcbde449a3760368c06e5a9f0b7|bf65fd4538110ad0046eafd8266a8ae59cff8aa61ad4378c2f56faf913eeb5c5|bf65fd4538110ad0046eafd8266a8ae59cff8aa61ad4378c2f56faf913eeb5c5', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the southern outskirts of Gadir-Gades, perhaps as early as the 8th century BC, the Temple of Hercules Gaditanus was dedicated to Melqart, then Hercules. Hannibal and Caesar paid respect."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple lay on the southern outskirts of Gadir-Gades [S1]; it perhaps dates as early as the 8th century BC [S1]; it was initially dedicated to Melqart [S4]; it was then dedicated to Hercules [S4]; Hannibal paid respect to it [S3]; Caesar paid respect to it [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Hercules Gaditanus was a place of worship (temple) at Gadir-Gades, present-day Cadiz, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hercules_Gaditanus]; It stood on the southern outskirts of Gadir-Gades [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hercules_Gaditanus]; It dates perhaps as early as the 8th century BC [SUPPORTED: https://ajaonline.org/article/1417/]; It was dedicated to Melqart, then to Hercules [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hercules_Gaditanus]; Hannibal paid respect at the temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hercules_Gaditanus]; Caesar paid respect at the temple [SUPPORTED: https://english.elpais.com/culture/2021-12-17/spanish-researchers-discover-possible-location-of-legendary-temple-of-hercules-gaditanus.html]"}]'::jsonb),
    ('657dbfe1-7b3f-4548-93c6-99be8674a6ff'::uuid, 'card_description', 'Built around 3000 BC on Sanday in Orkney — modelled closely on Maeshowe — this Neolithic cairn contained skeletal remains of multiple individuals when first opened in 1867.', 'On the Elsness peninsula of Sanday, Orkney, the Quoyness Chambered Cairn rests on an oval stone platform. Probably built around 3000 BC, it gave up the bones of several people in 1867.', 'teaser-card-s008:657dbfe1-7b3f-4548-93c6-99be8674a6ff:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '5290afefc9f4cfd60ad0183c85c33373abb4e775a3f3d4bf5e272efd4a9bf18e|0bc31fbb8dade0d8224c3d3312f7c9fb6048df517dc722efea2ac4eb7bedb527|0bc31fbb8dade0d8224c3d3312f7c9fb6048df517dc722efea2ac4eb7bedb527', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Elsness peninsula of Sanday, Orkney, the Quoyness Chambered Cairn rests on an oval stone platform. Probably built around 3000 BC, it gave up the bones of several people in 1867."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the cairn is on the Elsness peninsula [S5]; the peninsula is on Sanday, Orkney [S1]; the cairn sits on an oval stone platform [S6]; it was probably built around 3000 BC [S2]; the remains of several people were uncovered in the tomb in 1867 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Quoyness Chambered Cairn is a tomb (a Neolithic burial monument, a chambered cairn) on the island of Sanday in Orkney, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Quoyness_chambered_cairn]; It is located on the Elsness peninsula of Sanday, Orkney [SUPPORTED: https://en.wikipedia.org/wiki/Quoyness_chambered_cairn]; The cairn rests on an oval stone platform [SUPPORTED: https://en.wikipedia.org/wiki/Quoyness_chambered_cairn]; It was probably built around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Quoyness_chambered_cairn]; The bones of several people were found in it (during the excavation) in 1867 [SUPPORTED: https://en.wikipedia.org/wiki/Quoyness_chambered_cairn]"}]'::jsonb),
    ('660397b7-a480-4ae7-9742-5ff0970c8e31'::uuid, 'card_description', 'Inca-period site near Machu Picchu District, active 1438-1530 AD. Above the Willkanuta River left bank, it neighbours Machu Q''inti, Willkaraqay and Patallaqta - Quechua names evoking the hummingbird.', 'Above the left bank of the Willkanuta River, in Peru''s Machupicchu District, the archaeological site of Wayna Q''inti keeps company with Machu Q''inti, Willkaraqay and Patallaqta.', 'teaser-card-s008:660397b7-a480-4ae7-9742-5ff0970c8e31:card_description', 'teaser-card-s008 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'b47465be23b4ab976a85eace3f88d47e749f186e0f9662152b9319d93639bbd4|9a81e7581991248949fe61d56fface9f7cfc4a96d9d33f654f8442aa4868d5b3|9a81e7581991248949fe61d56fface9f7cfc4a96d9d33f654f8442aa4868d5b3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Above the left bank of the Willkanuta River, in Peru''s Machupicchu District, the archaeological site of Wayna Q''inti keeps company with Machu Q''inti, Willkaraqay and Patallaqta."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies above the left bank of the Willkanuta River [S3]; it is in Peru''s Machupicchu District [S1, S2]; Wayna Q''inti is an archaeological site [S1]; it is near the archaeological sites of Machu Q''inti, Willkaraqay and Patallaqta [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Wayna Q''inti is an archaeological site in Peru, in the Machupicchu District [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Q%27inti]; It lies above the left bank of the Willkanuta River [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Q%27inti]; It lies near (keeps company with) the site Machu Q''inti [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Q%27inti]; It lies near (keeps company with) the site Willkaraqay [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Q%27inti]; It lies near (keeps company with) the site Patallaqta [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Q%27inti]"}]'::jsonb),
    ('673d799c-45de-440d-9e65-df84ddf7ee95'::uuid, 'card_description', 'Chichester''s Roman predecessor, first a legionary winter fort in 43 AD for the invasion of Britain. The army left, and a proper Roman town grew in its place.', 'Chichester''s Roman heart, Noviomagus Reginorum, began as a winter fort for the Second Augustan Legion shortly after AD 43. Part of a fine Roman mosaic survives beneath the cathedral floor.', 'teaser-card-s008:673d799c-45de-440d-9e65-df84ddf7ee95:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '1a20965253e75de295c82254117c1c621957c91a41904b3ec5efd281d21f4ee1|78c66e0d43a6f3b5fc37130a1671fe00eed55db9fb3a333236853ba3cc343bf2|78c66e0d43a6f3b5fc37130a1671fe00eed55db9fb3a333236853ba3cc343bf2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chichester''s Roman heart, Noviomagus Reginorum, began as a winter fort for the Second Augustan Legion shortly after AD 43. Part of a fine Roman mosaic survives beneath the cathedral floor."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Noviomagus Reginorum was Chichester''s Roman heart [S1]; the settlement began as a winter fort [S3]; the fort was for the Second Augustan Legion [S3]; it was established shortly after AD 43 [S3]; part of a fine Roman mosaic survives [S8]; the mosaic lies beneath the floor of Chichester Cathedral [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Noviomagus Reginorum was Chichester''s Roman heart, i.e. the Roman town at Chichester (England) [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; Noviomagus Reginorum lies in Chichester, in the English county of West Sussex [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; It began as a winter fort [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; The winter fort was for the Second Augustan Legion [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; The winter fort was established shortly after AD 43 (the Roman invasion) [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; Part of a fine Roman mosaic survives (from the Roman town) [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]; The mosaic lies beneath the floor of the cathedral (Chichester Cathedral) [SUPPORTED: https://en.wikipedia.org/wiki/Noviomagus_Reginorum]"}]'::jsonb),
    ('67b015db-bcdf-4250-92e0-d43ef1237e4b'::uuid, 'card_description', 'Iron Age Castro culture settlement on the Lima River estuary, occupied during initial Roman colonisation of northwest Iberia — from the late 1st century BC to around 70 AD.', 'On the Lima River estuary, the Castro of Vieito lasted a century: a settlement considered modest, with a wall with monumental entrance-ways, a circular great house and Roman coins.', 'teaser-card-s008:67b015db-bcdf-4250-92e0-d43ef1237e4b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'b4b2f1b2a6eb08b58f2343bebdf9f9ea39b8519893257900d58dc080614264a2|43c578e3909f0a702379664156cc01f0526901186452927f00b0c612705311b8|43c578e3909f0a702379664156cc01f0526901186452927f00b0c612705311b8', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Lima River estuary, the Castro of Vieito lasted a century: a settlement considered modest, with a wall with monumental entrance-ways, a circular great house and Roman coins."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the castro lies on the Lima River estuary [S1]; the settlement lasted a century [S2]; the settlement is considered modest [S3]; it had a wall with monumental entrance-ways [S3]; it had a circular great house [S3]; Roman coins were found there [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Castro of Vieito is a settlement (a castro-culture archaeological site) on the Lima River estuary, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]; The settlement lasted a century [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]; The settlement is considered modest [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]; It had a wall with monumental entrance-ways [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]; It had a circular great house [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]; Roman coins were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Vieito]"}]'::jsonb),
    ('68181f11-04ab-4bfb-aedb-0c7bc0ebb2f8'::uuid, 'card_description', 'Listoghil is the large central monument in the Carrowmore group of prehistoric tombs in County Sligo.', 'Listoghil spans about 34 meters at the heart of the Carrowmore tombs, ringed by about 35 monuments. Antiquarians recorded finding ''bones of horses'', charred wood and a flint javelin head.', 'teaser-card-s008:68181f11-04ab-4bfb-aedb-0c7bc0ebb2f8:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '0f04a9e619c3c8c21ad556e6fdd9b21e8e0e5f9395daf20c913ebf2049ff61a8|ac82dc7be25e337c5a5fab4ff0213eea23ed155904adfd7f9910b5eecac78849|ac82dc7be25e337c5a5fab4ff0213eea23ed155904adfd7f9910b5eecac78849', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Listoghil spans about 34 meters at the heart of the Carrowmore tombs, ringed by about 35 monuments. Antiquarians recorded finding ''bones of horses'', charred wood and a flint javelin head."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Listoghil spans about 34 meters [S5]; it stands at the heart of the Carrowmore tombs [S1]; about 35 monuments surround it [S2]; antiquarians recorded finding ''bones of horses'' [S6]; antiquarians recorded finding charred wood [S6]; antiquarians recorded finding a flint javelin head [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Listoghil is a tomb: the large central monument of the Carrowmore group of prehistoric tombs (County Sligo, Ireland) [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; Listoghil stands at the heart of the Carrowmore tombs [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; Listoghil spans about 34 meters [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; It is ringed by about 35 monuments [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; Antiquarians recorded finding ''bones of horses'' [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; Antiquarians recorded finding charred wood [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]; Antiquarians recorded finding a flint javelin head [SUPPORTED: https://en.wikipedia.org/wiki/Listoghil]"}]'::jsonb),
    ('69e127d4-7ea5-44b8-8b0b-b1b7fb000531'::uuid, 'card_description', NULL, 'Known as the Altar of the Moors, the Mausoleum of the Atilii was raised in local sandstone in the 2nd or 3rd centuries AD beside a Roman road. Only its facade survives.', 'teaser-card-s008:69e127d4-7ea5-44b8-8b0b-b1b7fb000531:card_description', 'teaser-card-s008 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '95439b2af02c7d32782383351dc5ff17a58f27597529ba3d2105ce3e72d76750|1dd356c7879f3e22aff4ca019957a02d1223ea2be136177a355813e771b5de82|1dd356c7879f3e22aff4ca019957a02d1223ea2be136177a355813e771b5de82', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Known as the Altar of the Moors, the Mausoleum of the Atilii was raised in local sandstone in the 2nd or 3rd centuries AD beside a Roman road. Only its facade survives."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the mausoleum is known as the Altar of the Moors [S1]; it was built in local sandstone [S6]; it dates from the 2nd or 3rd centuries AD [S1]; it stands beside a Roman road [S2]; only its facade survives [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Mausoleum of the Atilii is a Roman mausoleum (a tomb) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]; It is known as the Altar of the Moors [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]; It was built in local sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]; It dates to the 2nd or 3rd centuries AD [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]; It stood beside a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]; Only its facade survives [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_the_Atilii]"}]'::jsonb),
    ('69ef4043-f69f-4f87-b422-09eb53a72950'::uuid, 'card_description', 'Occupied from 7000 BC, this cave near Rasines contains Paleolithic paintings alongside some of the longest karst cavities in the world. The Silencio River rises from within its chambers.', 'The Silencio River rises in Cave del Valle, one of the longest explored caves in the world. Finds include Azilian harpoons, Upper Magdalenian spear points and a decorated stick, now lost.', 'teaser-card-s008:69ef4043-f69f-4f87-b422-09eb53a72950:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '347af1c1c7e512e23d8cbcec5e65d5b017de9a464bc34f389197d7fb145ef21f|05d34038024f9809013fe3b115f86f1f797f6e4a7aeb6f1af149360fa96a159b|05d34038024f9809013fe3b115f86f1f797f6e4a7aeb6f1af149360fa96a159b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Silencio River rises in Cave del Valle, one of the longest explored caves in the world. Finds include Azilian harpoons, Upper Magdalenian spear points and a decorated stick, now lost."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Silencio River rises in Cave del Valle [S2]; it is one of the longest explored caves in the world [S6]; Azilian harpoons are documented finds [S3]; Upper Magdalenian spear points are documented finds [S3]; a decorated stick was found at the site [S5]; the decorated stick is now lost [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Cave del Valle is a cave in Cantabria, Spain (near El Cerro, municipality of Rasines) [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; The Silencio River rises in Cave del Valle [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; It is one of the longest explored caves in the world [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; Finds include Azilian harpoons [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; Finds include Upper Magdalenian spear points [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; Finds include a decorated stick [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]; The decorated stick is now lost [SUPPORTED: https://en.wikipedia.org/wiki/Cave_del_Valle_(Cantabria)]"}]'::jsonb),
    ('6a067823-7f9a-4a72-95c6-ff86153ffbac'::uuid, 'card_description', 'The ancient Lycian city of Myra, home of Saint Nicholas — the real person behind Santa Claus. Rock-cut tombs and a Roman theatre share the site with his church.', 'Demre was once Myra, home of Saint Nicholas and one of the most important city-states of ancient Lycia, set on the coast of the Teke peninsula with the Taurus Mountains rising behind.', 'teaser-card-s008:6a067823-7f9a-4a72-95c6-ff86153ffbac:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '764c34a14628589dbc6c9d3dec2120c5edd617b6fa65c1b3bf8e0416dd52ca34|06a76aaa3c473b9949c2c9d90e8436a03d33165feaaff3ef1073b4530b7701fa|06a76aaa3c473b9949c2c9d90e8436a03d33165feaaff3ef1073b4530b7701fa', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Demre was once Myra, home of Saint Nicholas and one of the most important city-states of ancient Lycia, set on the coast of the Teke peninsula with the Taurus Mountains rising behind."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Demre was once Myra [S1, S3]; Myra was the home of Saint Nicholas [S1]; Myra was one of the most important city-states of ancient Lycia [S3]; it lies on the coast of the Teke peninsula [S2]; the Taurus Mountains lie behind it [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Demre is the ancient Lycian town of Myra, a settlement in Turkey [SUPPORTED: https://en.wikipedia.org/wiki/Demre]; Myra was the home of Saint Nicholas [SUPPORTED: https://en.wikipedia.org/wiki/Demre]; Myra was one of the most important city-states of ancient Lycia [SUPPORTED: https://en.wikipedia.org/wiki/Demre]; It is set on the coast of the Teke peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Demre]; The Taurus Mountains rise behind it [SUPPORTED: https://en.wikipedia.org/wiki/Demre]"}]'::jsonb),
    ('6a8bc59c-77c3-4359-8f65-19f67ee0ac04'::uuid, 'card_description', 'Astale was a Roman town of ancient Crete. The site of Astale is located near modern Bali.', 'Near modern Bali, on the north coast of Crete, lay Astale, a Roman town and the harbour of Axus. The Stadiasmus Maris Magni placed it 300 stadia from Herakleion.', 'teaser-card-s008:6a8bc59c-77c3-4359-8f65-19f67ee0ac04:card_description', 'teaser-card-s008 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '2db13f5bae11480a71765a3cf1534277e546bc40bc7ba864c607b1e41195d00d|25bf60d48ad66fe9389f99f4ec9aa918bf41c2602405ed7ddeb9f67e5c191ac7|25bf60d48ad66fe9389f99f4ec9aa918bf41c2602405ed7ddeb9f67e5c191ac7', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near modern Bali, on the north coast of Crete, lay Astale, a Roman town and the harbour of Axus. The Stadiasmus Maris Magni placed it 300 stadia from Herakleion."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is near modern Bali [S4]; Astale lay on the north coast of Crete [S2]; Astale was a Roman town [S1]; it was the harbour of Axus [S3]; the Stadiasmus Maris Magni placed it 300 stadia from Herakleion [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Astale was a Roman town of ancient Crete [SUPPORTED: https://en.wikipedia.org/wiki/Astale]; It lay on the north coast of Crete [SUPPORTED: https://en.wikipedia.org/wiki/Astale]; The site is near modern Bali [SUPPORTED: https://en.wikipedia.org/wiki/Astale]; Astale was the harbour of Axus [SUPPORTED: https://en.wikipedia.org/wiki/Astale]; The Stadiasmus Maris Magni placed Astale 300 stadia from Herakleion [SUPPORTED: https://en.wikipedia.org/wiki/Astale]"}]'::jsonb),
    ('6adb5ed9-34b6-4985-8d4f-ece2fcdd31e4'::uuid, 'card_description', 'A Roman fort founded around 80 AD, rebuilt multiple times over four centuries. Its garrison helped defend the northwest coast against Irish Sea raiders.', 'Atop Castle Hill, Lancaster Roman Fort began in timber, probably around 80 AD, likely to command a crossing of the River Lune. Its south side is presumed to lie under Lancaster Castle.', 'teaser-card-s008:6adb5ed9-34b6-4985-8d4f-ece2fcdd31e4:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '0aeb9013dc8031821b5f35c7e096e8b82d4b33cbe6e1f1be44ad2084c4da1bc7|d4f28b5d195870fc6b834168c8bdfcecbcbe31c374e384899162bef757d89842|d4f28b5d195870fc6b834168c8bdfcecbcbe31c374e384899162bef757d89842', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-012", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Atop Castle Hill, Lancaster Roman Fort began in timber, probably around 80 AD, likely to command a crossing of the River Lune. Its south side is presumed to lie under Lancaster Castle."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the fort lies atop Castle Hill [S1]; it began as a timber fort [S2]; it was probably built around 80 AD [S2]; it was likely built there to command a crossing of the River Lune [S3]; its south side is presumed to lie under Lancaster Castle [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Lancaster Roman Fort is a ruined Roman fort atop Castle Hill in Lancaster, England [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Roman_Fort]; The first fort was built in timber [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Roman_Fort]; It was probably built around 80 AD [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Roman_Fort]; It was likely sited to command a crossing of the River Lune [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Roman_Fort]; Its south side is presumed to lie under Lancaster Castle [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Roman_Fort]"}]'::jsonb),
    ('6b703aad-2def-4538-8acf-b3ff22972f76'::uuid, 'card_description', 'A cluster of 4th-millennium BC passage tombs spread across a hilltop range, decorated with rare megalithic art. At the equinox, sunlight enters one cairn and illuminates carvings on its back wall.', 'On four hilltops at Loughcrew, the highest point in Meath, ancient passage tombs keep watch, some decorated with rare megalithic art and estimated to date from about 3300 BC.', 'teaser-card-s008:6b703aad-2def-4538-8acf-b3ff22972f76:card_description', 'teaser-card-s008 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '153713bdc777479764e06bd7b88ec8f817eb57c3ce3d7172144530ecb9e6b09a|352b4c8cb72ee2d3c737c1f4df2c312b746919ea7c6b500600d98335ccac3aed|352b4c8cb72ee2d3c737c1f4df2c312b746919ea7c6b500600d98335ccac3aed', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On four hilltops at Loughcrew, the highest point in Meath, ancient passage tombs keep watch, some decorated with rare megalithic art and estimated to date from about 3300 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the tombs are at Loughcrew [S1, S2]; the monuments stand on four hilltops [S5]; Loughcrew''s hills and tombs are the highest point in Meath [S3]; the tombs are ancient [S2]; the tombs are passage tombs [S4]; some of the tombs are decorated with megalithic art [S2]; the megalithic art is rare [S2]; the monuments are estimated to date from about 3300 BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Loughcrew is a site of ancient passage tombs (one of Ireland''s passage tomb cemeteries) [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; Loughcrew is in County Meath, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The tombs are spread over four hilltops [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The tombs sit on top of hills (they keep watch from the hilltops) [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The hills with the tombs are the highest point in Meath [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The tombs are ancient (4th millennium BC) [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; Some (not all) of the tombs are decorated with megalithic art [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The megalithic art at Loughcrew is rare [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]; The tombs are estimated to date from about 3300 BC [SUPPORTED: https://en.wikipedia.org/wiki/Loughcrew]"}]'::jsonb),
    ('6bb8492b-2731-4f5a-8b48-4eb6b3b851f8'::uuid, 'card_description', 'A Celtic chieftain buried in 530 BC on a 3-metre bronze couch with gold shoes and a gold torc. The 60-metre burial mound had shrunk to 1 metre before excavation.', 'In the Celtic Hochdorf Chieftain''s Grave, a man lay on a bronze couch with eight wheels, and at its foot stood a cauldron ringed by three lions, once filled with about 400 L of mead.', 'teaser-card-s008:6bb8492b-2731-4f5a-8b48-4eb6b3b851f8:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '1b4fced9676110e65ea0f713734d410483054e4a5a5078f8fe87f5d7101d6511|123c779597a2b040c0f1f4575ce265d5d8072934380de320774cb7fee25231dc|123c779597a2b040c0f1f4575ce265d5d8072934380de320774cb7fee25231dc', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the Celtic Hochdorf Chieftain''s Grave, a man lay on a bronze couch with eight wheels, and at its foot stood a cauldron ringed by three lions, once filled with about 400 L of mead."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the grave is Celtic [S1]; a man lay in the burial chamber on a couch [S3]; the couch is bronze [S3]; the couch has eight wheels [S3]; a cauldron stood at the foot of the couch [S4]; the cauldron is decorated with three lions around its brim [S4]; the cauldron was once filled with about 400 L of mead [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Hochdorf Chieftain''s Grave is a Celtic burial chamber (a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]; The grave is in Germany (Baden-Württemberg) [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]; A man was laid out on a bronze couch in the grave [SUPPORTED: https://www.laits.utexas.edu/ironagecelts/hochdorf1.php]; The bronze couch had eight wheels [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]; A cauldron stood at the foot of the couch [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]; The cauldron was ringed by three lions [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]; The cauldron was originally filled with about 400 L of mead (German museum sources give a 500 L capacity filled about three quarters, roughly 375 L) [SUPPORTED: https://en.wikipedia.org/wiki/Hochdorf_Chieftain%27s_Grave]"}]'::jsonb),
    ('6bedf225-fc80-4324-9f91-eaa70bdcc002'::uuid, 'card_description', 'The site with paintings of llamas lies in a valley named Wakanwayq''u at a height of about 3,535 metres.', 'About 3,535 metres up in the valley of Wakanwayq''u, in the Cusco Region, llamas painted on the rock at Llamachayuq Qaqa wait for anyone who comes looking for them.', 'teaser-card-s008:6bedf225-fc80-4324-9f91-eaa70bdcc002:card_description', 'teaser-card-s008 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '6e0bc853179df9157ce6cd01acaff1c0ef89c2ede0e7465f099f5f5762230e6f|a5ad93dcdf69a98f2bf53327d8f92638aff7f9f4bf4da0c00797001b3166900e|a5ad93dcdf69a98f2bf53327d8f92638aff7f9f4bf4da0c00797001b3166900e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "About 3,535 metres up in the valley of Wakanwayq''u, in the Cusco Region, llamas painted on the rock at Llamachayuq Qaqa wait for anyone who comes looking for them."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies at a height of about 3,535 metres [S3]; it lies in the valley of Wakanwayq''u [S3]; it lies in the Cusco Region [S2]; llamas are painted at the site [S3]; the paintings are on rock [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Llamachayuq Qaqa is an archaeological site with rock paintings in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Llamachayuq_Qaqa]; The site is in the Cusco Region [SUPPORTED: https://en.wikipedia.org/wiki/Llamachayuq_Qaqa]; The rock paintings show llamas [SUPPORTED: https://en.wikipedia.org/wiki/Llamachayuq_Qaqa]; The site lies in the valley of Wakanwayq''u [SUPPORTED: https://en.wikipedia.org/wiki/Llamachayuq_Qaqa]; The site lies at a height of about 3,535 metres [SUPPORTED: https://en.wikipedia.org/wiki/Llamachayuq_Qaqa]"}]'::jsonb),
    ('6cb3213a-bb68-4b7b-b45f-fab324033b3c'::uuid, 'card_description', 'Round Bronze Age cairn in Ceredigion, about 2 metres long, with its capstone fallen and side slabs still in position. The grave bears no proven connection to the 6th-century poet Taliesin.', 'Legend calls Bedd Taliesin the grave of the poet Taliesin, though no connection is proven: a Bronze Age cairn in Ceredigion with a cist about 2m long, its capstone fallen.', 'teaser-card-s008:6cb3213a-bb68-4b7b-b45f-fab324033b3c:card_description', 'teaser-card-s008 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '6e62af84f99d511d968fe7ad84e5b53b2b1893031b40c637a539f442388ff331|526cf6e1ea7b1f4deacc0d273e74052b35fb927b197543d63859479b87020f4a|526cf6e1ea7b1f4deacc0d273e74052b35fb927b197543d63859479b87020f4a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Legend calls Bedd Taliesin the grave of the poet Taliesin, though no connection is proven: a Bronze Age cairn in Ceredigion with a cist about 2m long, its capstone fallen."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "legend names Bedd Taliesin the grave of the poet Taliesin [S1]; no connection between the cairn and Taliesin is proven [S5]; the monument is a Bronze Age cairn [S2]; it is in Ceredigion [S1]; it has a cist about 2m long [S3]; its capstone has fallen [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bedd Taliesin is a Bronze Age burial cairn [SUPPORTED: https://coflein.gov.uk/en/sites/303607]; The cairn is in Ceredigion (Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Bedd_Taliesin]; Legend calls Bedd Taliesin the grave of the poet Taliesin [SUPPORTED: https://en.wikipedia.org/wiki/Bedd_Taliesin]; No connection between the cairn and Taliesin is proven [SUPPORTED: https://en.wikipedia.org/wiki/Bedd_Taliesin]; The cairn has a cist about 2m long [SUPPORTED: https://en.wikipedia.org/wiki/Bedd_Taliesin]; The capstone of the cist has fallen [SUPPORTED: https://en.wikipedia.org/wiki/Bedd_Taliesin]"}]'::jsonb),
    ('6cc8d849-0080-41c6-8082-b713db44f82b'::uuid, 'card_description', 'Sea cliffs 15–25 metres high defend three sides of this St Mary''s promontory fort; three banks and ditches guard the landward approach. The rocky headland covers 0.4 hectares.', 'On St Mary''s in the Isles of Scilly, the Iron Age fort of Giant''s Castle holds a rocky promontory, guarded by sea cliffs 15 to 25 metres high and by three banks and ditches.', 'teaser-card-s008:6cc8d849-0080-41c6-8082-b713db44f82b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'fe7dda6bfe7e830ac2db3d4e8a9fc623d70cfe9c9726d7e885f47a099e6da482|58efa0a275ac1de3b71550b5ad72be791fd401909073a42679d20accf3d375a5|58efa0a275ac1de3b71550b5ad72be791fd401909073a42679d20accf3d375a5', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On St Mary''s in the Isles of Scilly, the Iron Age fort of Giant''s Castle holds a rocky promontory, guarded by sea cliffs 15 to 25 metres high and by three banks and ditches."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is on St Mary''s in the Isles of Scilly [S1]; it is an Iron Age fort [S1]; the fort holds a rocky promontory [S1, S4]; the promontory is guarded by sea cliffs 15 to 25 metres high [S4]; it is guarded by three banks and ditches [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-037 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Giant''s Castle is an Iron Age promontory fort (fort) [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]; Giant''s Castle is on St Mary''s, Isles of Scilly [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]; The fort holds a rocky promontory [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]; The promontory is guarded by sea cliffs [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]; The sea cliffs are 15 to 25 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]; The promontory is also guarded by three banks and ditches [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Castle,_Isles_of_Scilly]"}]'::jsonb),
    ('6d04a9ad-3da8-415b-a69a-2f3343244e67'::uuid, 'card_description', 'The site is situated on the periphery of Guifões, on the eastern flank of a hilltop overlooking the town, surrounded by pine forests, overlooking the Leça River.', 'Three lines of walls defend the Castro of Monte Castelo, a fortified settlement among pine forests above the Leça River, where excavation unearthed homes of circular and rectangular plans.', 'teaser-card-s008:6d04a9ad-3da8-415b-a69a-2f3343244e67:card_description', 'teaser-card-s008 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8d963ebcb945492949b736171e5f6c128620af493332044bb628a2bcece084a8|b2e5ae9d2649ad5babe64e9c9fb35c69ebc81e41403151d08b3d556678b3313e|b2e5ae9d2649ad5babe64e9c9fb35c69ebc81e41403151d08b3d556678b3313e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Three lines of walls defend the Castro of Monte Castelo, a fortified settlement among pine forests above the Leça River, where excavation unearthed homes of circular and rectangular plans."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "three lines of walls defend the settlement [S4]; the Castro of Monte Castelo is a fortified settlement [S1]; it is surrounded by pine forests [S3]; it overlooks the Leca River [S3]; excavation unearthed homes of circular and rectangular plans [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Castro of Monte Castelo is a fortified settlement (in Matosinhos, Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Monte_Castelo]; Three lines of walls defend the fortified settlement [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Monte_Castelo]; The site lies among pine forests [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Monte_Castelo]; The site lies above the Leça River [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Monte_Castelo]; Excavation unearthed homes of circular and rectangular plans [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Monte_Castelo]"}]'::jsonb),
    ('6d16aa73-aa0a-4c85-bb33-79b2bb01c0ef'::uuid, 'card_description', 'A Roman villa now submerged under a reservoir. Before the waters rose, the 28-metre main house, bathhouse, and courtyard were fully recorded.', 'Raised on a platform, presumably to keep it dry, the Carsington Roman Villa of sandstone and gritstone now lies submerged under the Carsington Water reservoir, bathhouse and all.', 'teaser-card-s008:6d16aa73-aa0a-4c85-bb33-79b2bb01c0ef:card_description', 'teaser-card-s008 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '84a948de9b309bdc44d25778838695cd4b254fedaa10c737881cc2c19f232b43|14c7961348f20cfae3971c673312dcab1361688251b57bffeddc03d6b3ac744d|14c7961348f20cfae3971c673312dcab1361688251b57bffeddc03d6b3ac744d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Raised on a platform, presumably to keep it dry, the Carsington Roman Villa of sandstone and gritstone now lies submerged under the Carsington Water reservoir, bathhouse and all."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the villa was built on a raised platform [S6]; the platform was presumably to keep the villa dry [S6]; the villa is Roman [S1]; the villa was built of sandstone and gritstone [S7]; the site now lies submerged under the Carsington Water reservoir [S2]; the villa includes a bathhouse [S3, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Carsington Roman Villa is a Roman villa at Carsington near Wirksworth, Derbyshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]; The villa was raised on a platform [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]; The platform is presumed to have kept the villa dry [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]; The villa was built of sandstone and gritstone [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]; The site now lies submerged under the Carsington Water reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]; The villa had a bathhouse [SUPPORTED: https://en.wikipedia.org/wiki/Carsington_Roman_Villa]"}]'::jsonb),
    ('6de0d66c-8252-46f9-9f71-dd6210234681'::uuid, 'card_description', 'Caves used from 78,000 BC, yielding a Neanderthal jawbone, bone flutes, and cave paintings. Stone tools span the Aurignacian through Magdalenian periods.', 'In the foothills of the Pyrenees, the Isturitz and Oxocelhaya Caves hold cave paintings and gave up bone flutes, a Neanderthal jaw and Magdalenian skull vaults cut into drinking cups.', 'teaser-card-s008:6de0d66c-8252-46f9-9f71-dd6210234681:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '01eba9550d57b3b84d28a0f61aedd19701be3dcbbbf24cb7ee2db459d2057c2e|bd3019dd7b345d995c57c683a9f7a58193c54e1ffdf2132e73805b72d3cbb039|bd3019dd7b345d995c57c683a9f7a58193c54e1ffdf2132e73805b72d3cbb039', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the foothills of the Pyrenees, the Isturitz and Oxocelhaya Caves hold cave paintings and gave up bone flutes, a Neanderthal jaw and Magdalenian skull vaults cut into drinking cups."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the caves are in the foothills of the Pyrenees [S3]; the caves include cave paintings [S2]; the caves include bone flutes [S2]; a Neanderthal mandible was found there [S1]; Magdalenian cranial vaults were modified into drinking cups [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Isturitz and Oxocelhaya Caves are a cave site (an important Paleolithic site) in southwestern France [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; The caves are in the foothills of the Pyrenees [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; The caves hold cave paintings [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; The caves gave up bone flutes [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; A Neanderthal jaw (mandible) was found there [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; Human skull vaults (cranial vaults) were found there, cut and modified into drinking cups [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]; The skull-vault drinking cups date from the Magdalenian [SUPPORTED: https://en.wikipedia.org/wiki/Isturitz_and_Oxocelhaya_caves]"}]'::jsonb),
    ('6e696e62-f344-4f80-8460-275fd591249b'::uuid, 'card_description', 'An ancient mountain settlement with cisterns, wineries, and olive presses built in polygonal masonry. A three-nave basilica shows later Byzantine reuse.', 'In the Taurus Mountains lies Işıkkale, the castle of light, its original name not known: a settlement of cisterns, wineries and olive oil presses, most of its buildings in polygonal masonry.', 'teaser-card-s008:6e696e62-f344-4f80-8460-275fd591249b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'd0fddfae0514ea97507a21a693f5c6e1ab42c14cb5f6ce6355aed1adafa017d2|8b15b77ee41de25842cbfbf0cfbfc61c29a431232f14e79410f6706b38bf00c8|8b15b77ee41de25842cbfbf0cfbfc61c29a431232f14e79410f6706b38bf00c8', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the Taurus Mountains lies Işıkkale, the castle of light, its original name not known: a settlement of cisterns, wineries and olive oil presses, most of its buildings in polygonal masonry."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies in the Taurus Mountains [S3]; the name Işıkkale means castle of light [S1]; the original name of the settlement is not known [S5]; the site is a settlement [S1]; it has cisterns [S7]; it has wineries [S7]; it has olive oil presses [S7]; most of the buildings use polygonal masonry [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Işıkkale is an ancient settlement in Turkey (Silifke district, Mersin Province) [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; Işıkkale lies in the Taurus Mountains [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; The name Işıkkale means castle of light [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; The original name of the settlement is not known [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; The settlement has cisterns [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; The settlement has wineries [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; The settlement has olive oil presses [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]; Most of its buildings are in polygonal masonry [SUPPORTED: https://en.wikipedia.org/wiki/I%C5%9F%C4%B1kkale]"}]'::jsonb),
    ('6eaec8c3-97e1-4e7b-b1d8-96b14c96a323'::uuid, 'card_description', '4500–3500 BC. A late Neolithic and early Eneolithic site in Šumadija — part of the Vinča culture''s final phase, when the first evidence of metallurgy appeared before the culture vanished.', 'Medvednjak, a large Vinča culture settlement of 4500-3500 BC in Šumadija, left figurines of high artistic value, among them one called Woman in labor for its contracted position.', 'teaser-card-s008:6eaec8c3-97e1-4e7b-b1d8-96b14c96a323:card_description', 'teaser-card-s008 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '4e1cc23b84d1c48918bc2e1173f8bee59e6a0b5ecf5fe1db815f073cb76b87de|fa7c691a9ab621366b059fa36f0c2ed7a56644eb0baa3bc62aa3a21850146e78|fa7c691a9ab621366b059fa36f0c2ed7a56644eb0baa3bc62aa3a21850146e78', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Medvednjak, a large Vinča culture settlement of 4500-3500 BC in Šumadija, left figurines of high artistic value, among them one called Woman in labor for its contracted position."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Medvednjak is in the Šumadija region [S1]; it is a settlement [S4]; the settlement was large [S4]; it belongs to the Vinča culture [S3]; it dates to 4500-3500 BC [S3]; it yielded figurines of high artistic value [S5]; one figurine is called Woman in labor [S6]; the figurine is so called for its contracted position [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-038 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Medvednjak is an archaeological site (a settlement) in central Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; Medvednjak is in the Šumadija region [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; Medvednjak belongs to the Vinča culture [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; The settlement dates to 4500-3500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; Medvednjak was a large settlement [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; Medvednjak yielded figurines of high artistic value [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; One of the figurines is called Woman in labor [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]; The figurine is called Woman in labor because of its contracted position [SUPPORTED: https://en.wikipedia.org/wiki/Medvednjak]"}]'::jsonb),
    ('6ec6df2d-af82-49d5-8e37-1309ddc4793b'::uuid, 'card_description', 'Small Inca complex at 3,590 metres on the flank of Inka Wasi, above the Apurimac gorge south of Choquequirao. A high-altitude staging post on the edge of the empire''s most dramatic terrain.', 'In Quechua its name means Inca ruin, an old building of walls without a roof: Inka Raqay, a small complex 3,590 metres up on the northern slope of Inka Wasi, above the Apurímac River.', 'teaser-card-s008:6ec6df2d-af82-49d5-8e37-1309ddc4793b:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '78ba42edb1de6b6124617c2a64e9a03e96afe51305f7c0731d1164918cf3e616|3287132811125eece1a9eb7f75427c107ac384b638015e150a3cbd03fa676601|3287132811125eece1a9eb7f75427c107ac384b638015e150a3cbd03fa676601', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Quechua its name means Inca ruin, an old building of walls without a roof: Inka Raqay, a small complex 3,590 metres up on the northern slope of Inka Wasi, above the Apurímac River."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in Quechua the name means Inca ruin [S1]; raqay means an old building of walls without a roof [S1]; Inka Raqay is a small complex [S1]; it lies at a height of 3,590 metres [S3]; it is on the northern slope of Inka Wasi [S3]; it is above the Apurímac River [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Inka Raqay is a small archaeological complex (ruin site) in Peru, in the Apurímac Region [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]; In Quechua the name means Inca ruin (inka = Inca, raqay = ruin) [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]; The Quechua word raqay describes an old building of walls without a roof [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]; The complex lies at 3,590 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]; It is on the northern slope of Inka Wasi [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]; It lies above the Apurímac River [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Apur%C3%ADmac]"}]'::jsonb),
    ('6f759cf6-fe55-4567-b1d1-26b536e8352e'::uuid, 'card_description', 'A Maya city whose carved stone lintels are among the finest surviving examples of Classic Maya art. The hieroglyphic texts record detailed dynastic histories.', 'On a terrace above the Usumacinta River, the Maya city of Yaxchilan keeps sculptured stone lintels above its doorways, their hieroglyphic texts recounting the history of its dynasty.', 'teaser-card-s008:6f759cf6-fe55-4567-b1d1-26b536e8352e:card_description', 'teaser-card-s008 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '26ae0526df30ae8b10a6d70f4445405ea91ca72926cb941cc56569876c223044|cd2601a74c6670cc9eebc716668c68d047a5981a4cec36ea2e0ebda2d22d79b6|cd2601a74c6670cc9eebc716668c68d047a5981a4cec36ea2e0ebda2d22d79b6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a terrace above the Usumacinta River, the Maya city of Yaxchilan keeps sculptured stone lintels above its doorways, their hieroglyphic texts recounting the history of its dynasty."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the ruins stand on a terrace above the Usumacinta River [S7]; Yaxchilan is a Maya city [S1]; it has sculptured stone lintels [S3]; the lintels are set above doorways [S3]; the lintels carry hieroglyphic texts [S4]; the texts describe the dynastic history of the city [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Yaxchilan is a Maya city (ancient Maya city) [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; The city lies on the Usumacinta River [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; Its palaces and temples stand on a terrace above the Usumacinta River [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; The site keeps sculptured stone lintels [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; The lintels are set above the doorways of the buildings [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; The lintels carry hieroglyphic texts [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]; The hieroglyphic texts recount the history of the city''s dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Yaxchilan]"}]'::jsonb),
    ('6ff3e4f1-8f21-410a-9c93-d4468c91a762'::uuid, 'card_description', 'Evidence from archaeological excavations at the site since 2005 indicates that there was continuous human habitation from 10,000 BP to 6,000 BP.', 'Stones taken from the spring at Blick Mead, about a mile east of Stonehenge, turn bright red in the air within hours. Here 70,000 worked flints and 2400 animal bones were found.', 'teaser-card-s008:6ff3e4f1-8f21-410a-9c93-d4468c91a762:card_description', 'teaser-card-s008 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '85e017402d7ec60745838143eb41fbc382fc761f05ca1aff2e5ec3cc1249efac|7289aac5e9d0def441c671a7cfcc55f5121f282b95968263e346e6b2110678ee|7289aac5e9d0def441c671a7cfcc55f5121f282b95968263e346e6b2110678ee', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Stones taken from the spring at Blick Mead, about a mile east of Stonehenge, turn bright red in the air within hours. Here 70,000 worked flints and 2400 animal bones were found."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Blick Mead has a spring [S1]; stones taken from the spring turn bright red on exposure to air [S6]; the stones turn red within hours [S6]; Blick Mead is about a mile east of Stonehenge [S2]; 70,000 worked flints were found at the site [S4]; 2400 animal bones were found at the site [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Blick Mead is a spring (chalkland spring in Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; The spring is about a mile east of Stonehenge [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; Stones taken from the spring turn bright red [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; The stones turn red on exposure to air, within hours [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; 70,000 worked flints were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; 2400 animal bones were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]; The flints and bones were found at Blick Mead itself [SUPPORTED: https://en.wikipedia.org/wiki/Blick_Mead]"}]'::jsonb),
    ('716136a2-65cf-4741-8874-9d09b17b8b91'::uuid, 'card_description', 'An unfinished open-air temple on Philae island, attributed to Emperor Trajan. It was dismantled and relocated in the 1960s to save it from rising Nile waters.', 'Locals call it Pharaoh''s Bed: Trajan''s Kiosk, an unfinished, roofless temple 15.85 metres high, once the entrance to Philae from the Nile, moved to Agilkia Island to escape rising waters.', 'teaser-card-s008:716136a2-65cf-4741-8874-9d09b17b8b91:card_description', 'teaser-card-s008 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '1eb4fe65cf683c5aa10cc9278c379638f0d1400ba4e4ea5bbf3b61b14c10c28a|0f424c1843d5569d9ba19fc4d71d985889a733b7d1d27c92c95d1f4c26e4eeef|0f424c1843d5569d9ba19fc4d71d985889a733b7d1d27c92c95d1f4c26e4eeef', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Locals call it Pharaoh''s Bed: Trajan''s Kiosk, an unfinished, roofless temple 15.85 metres high, once the entrance to Philae from the Nile, moved to Agilkia Island to escape rising waters."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "locals call it Pharaoh''s Bed [S1]; it is a temple [S1]; the monument is unfinished [S2]; the structure is roofless [S7]; it is 15.85 metres high [S6]; it once served as the entrance to Philae from the Nile [S4]; it was moved to Agilkia Island [S1, S5]; it was moved to escape the rising waters of the Nile [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Trajan''s Kiosk is a temple (hypaethral temple, now on Agilkia Island in southern Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; It is called Pharaoh''s Bed [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; The name Pharaoh''s Bed is used by the locals [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; The temple is unfinished [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; The structure is roofless today [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; It is 15.85 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; It once served as the entrance to Philae from the Nile [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; It was moved (relocated) to Agilkia Island [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]; The move was to escape the rising waters of the Nile [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Kiosk]"}]'::jsonb),
    ('722bf4c1-6dca-454a-9d27-89503114e75c'::uuid, 'card_description', 'A small cave sacred to Pan and the nymphs, known as "Lamp Cave" for the many oil lamps found inside. It has been identified as the setting for a comedy by Menander.', 'On Mount Parnes, the small Phyle Cave once held a sanctuary to Pan and the nymphs. So many oil lamps were found inside that it is also called Lychnospilia, the lamp cave.', 'teaser-card-s008:722bf4c1-6dca-454a-9d27-89503114e75c:card_description', 'teaser-card-s008 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', 'f025a67f8a2e34107d55c506d4dbd09a84aacf6c9b4f59f7cc3eaf0648c90dab|06b1bd2a60f2f1ee47109dcbdaec3d41a6380cdc791bca9015259e8fb34f8587|06b1bd2a60f2f1ee47109dcbdaec3d41a6380cdc791bca9015259e8fb34f8587', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Mount Parnes, the small Phyle Cave once held a sanctuary to Pan and the nymphs. So many oil lamps were found inside that it is also called Lychnospilia, the lamp cave."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the cave is on Mount Parnes [S1]; the cave is small [S1]; it was once the site of a sanctuary to Pan and the nymphs [S2]; a large number of oil lamps were found in the cave [S3]; it is also called Lychnospilia, the lamp cave [S3]; it is called Lychnospilia because of the oil lamps found there [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Phyle Cave is a small cave [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; The cave is on Mount Parnes [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; The cave once held a sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; The sanctuary was to Pan and the nymphs [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; Many oil lamps were found inside the cave [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; The cave is also called Lychnospilia [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]; Lychnospilia means lamp cave [SUPPORTED: https://en.wikipedia.org/wiki/Phyle_Cave]"}]'::jsonb),
    ('73cd4580-09d7-4bd4-9ec1-58c1fd18ef67'::uuid, 'card_description', 'A Phoenician colony near modern Almuñécar, active from at least the 3rd century BC. Its mint issued coins depicting Melqart — evidence of sustained Punic cultural identity even under Roman rule.', 'On the Mediterranean coast at Almuñécar lay Sexi, a Phoenician colony. Many of its coins of the 3rd-2nd centuries BC show the god Melqart on one face and one or two fish on the other.', 'teaser-card-s008:73cd4580-09d7-4bd4-9ec1-58c1fd18ef67:card_description', 'teaser-card-s008 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '63d6a5c812588ab4bd736807d32ab533d60fa59e3148932d9d9272e0516cf63f|7bb80f6856a0e08c7480093c9ece33396c77bef2ea33df0e599accd66324437d|7bb80f6856a0e08c7480093c9ece33396c77bef2ea33df0e599accd66324437d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Mediterranean coast at Almuñécar lay Sexi, a Phoenician colony. Many of its coins of the 3rd-2nd centuries BC show the god Melqart on one face and one or two fish on the other."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sexi lay on the Mediterranean coast at Almuñécar [S1]; Sexi was a Phoenician colony [S1]; many of its coins date to the 3rd-2nd centuries BC [S5]; many coins show the god Melqart on one face [S5]; many coins show one or two fish on the other face [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sexi was a Phoenician colony (a settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]; Sexi lay at the site of present-day Almuñécar, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]; Sexi lay on the Mediterranean coast [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]; Sexi issued a large corpus of coins in the 3rd-2nd centuries BC [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]; Many of these coins show the god Melqart on one face (the obverse) [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]; One or two fish appear on the other face (the reverse) of these coins [SUPPORTED: https://en.wikipedia.org/wiki/Sexi_(Phoenician_colony)]"}]'::jsonb),
    ('74a81d2a-f0a4-482b-ae66-15b51bbdb7ee'::uuid, 'card_description', 'Several coins dated up to the early 1st century CE, with none dated later, suggest a 1st-century CE date for the burial.', 'In six burial mounds at Tillya Tepe, five women and one man lay with about 20,600 ornaments, coins and artifacts of gold, silver and ivory: necklaces, belts, medallions and a crown.', 'teaser-card-s008:74a81d2a-f0a4-482b-ae66-15b51bbdb7ee:card_description', 'teaser-card-s008 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '71e33179250d6537c7adbaf431bbd2d90ad2012913ec91e00fc98744e3f90850|ec5ef9c6431503263c02c294223a0fa9dd53eb944b08825d4a4499f1a51cc3cf|ec5ef9c6431503263c02c294223a0fa9dd53eb944b08825d4a4499f1a51cc3cf', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In six burial mounds at Tillya Tepe, five women and one man lay with about 20,600 ornaments, coins and artifacts of gold, silver and ivory: necklaces, belts, medallions and a crown."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the burial mounds are at Tillya Tepe [S1, S3]; there are six burial mounds [S3]; the mounds hold five women and one man [S3]; they were buried with about 20,600 ornaments, coins and artifacts [S3]; the objects are of gold, silver and ivory [S3]; the ornaments include necklaces [S4]; the ornaments include belts [S4]; the ornaments include medallions [S4]; the ornaments include a crown [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tillya Tepe is an archaeological site in northern Afghanistan [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The burials lay in six burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; Five women were buried in the mounds [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; One man was buried in the mounds [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The dead lay with the rich objects (the finds come from the burial mounds) [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The finds number about 20,600 ornaments, coins and artifacts [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; Some of the objects are of gold [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; Some of the objects are of silver [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; Some of the objects are of ivory [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The finds include necklaces [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The finds include belts [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The finds include medallions [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]; The finds include a crown [SUPPORTED: https://en.wikipedia.org/wiki/Tillya_Tepe]"}]'::jsonb),
    ('754f8aff-b1ac-4650-a0db-89bf64dbbba5'::uuid, 'card_description', 'The bridge, which is believed to have been constructed at the end of the 1st century CE, was classified as a National Monument on 16 June 1910.', 'The Roman Bridge of Vila Formosa carried the road from Lisbon to Mérida over the Seda stream: six arches on stone pillars, gargoyles, and eyeholes to keep floods from bringing it down.', 'teaser-card-s008:754f8aff-b1ac-4650-a0db-89bf64dbbba5:card_description', 'teaser-card-s008 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'd1708076e2d2222811765c01a12708f0001fd0d80b28e3d325be8d0dc30a4468|b160dc64177036846764e526a3db43c9b62e16b0e3bd58c866060f8eb6600105|b160dc64177036846764e526a3db43c9b62e16b0e3bd58c866060f8eb6600105', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Bridge of Vila Formosa carried the road from Lisbon to Mérida over the Seda stream: six arches on stone pillars, gargoyles, and eyeholes to keep floods from bringing it down."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the bridge is Roman [S2, S7]; the bridge carried the road from Lisbon to Mérida [S2]; the bridge crosses the Seda stream [S1]; the bridge has six arches [S4]; the arches rest on stone pillars [S4]; the bridge was decorated with gargoyles [S6]; the bridge has eyeholes between the arches [S5]; the eyeholes were built to keep floods from bringing the bridge down [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Bridge of Vila Formosa is a Roman bridge in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The bridge crosses the Seda stream [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The bridge carried a road, part of the Roman road from Lisbon to Mérida [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The bridge has six arches [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The arches rest on stone pillars [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The bridge was decorated with gargoyles [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The bridge has eyeholes between the arches [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]; The eyeholes were meant to keep the bridge from collapsing in floods [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Vila_Formosa]"}]'::jsonb),
    ('75644a1d-350a-4750-a17f-bdae9a0e139f'::uuid, 'card_description', 'A Roman fort controlling a Pennine pass between Stainmore and the Aire gap. Its hilltop position provided unobstructed views across the entire valley.', 'On the summit of Brough Hill, where the Bain meets the Ure, the Roman fort of Virosidum traded its earth and timber rampart for stone around AD 190. Five ditches guard its west.', 'teaser-card-s008:75644a1d-350a-4750-a17f-bdae9a0e139f:card_description', 'teaser-card-s008 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'ac1e964178d6a1f1754c8db9aa618666fcd0f99a8e5ca11c7f86086505dd07c1|856f40d3d0193c7867a8c9069414a9e345a8199c24aca0403e719177d43a04a3|856f40d3d0193c7867a8c9069414a9e345a8199c24aca0403e719177d43a04a3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the summit of Brough Hill, where the Bain meets the Ure, the Roman fort of Virosidum traded its earth and timber rampart for stone around AD 190. Five ditches guard its west."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the fort stands on the summit of Brough Hill [S2]; the hill lies where the River Bain meets the River Ure [S2]; Virosidum was a Roman fort [S1]; the fort first had an earth and timber rampart [S4]; the rampart was rebuilt in stone around AD 190 [S4]; there are five ditches on the west side [S6]; the ditches serve as defences of the fort [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Virosidum was a Roman fort near Bainbridge in North Yorkshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The fort stands on the summit of Brough Hill [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; Brough Hill lies where the River Bain meets the River Ure [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The fort initially had an earth and timber rampart [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The rampart was rebuilt in stone [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The stone rebuilding took place around AD 190 [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The fort has five ditches [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]; The five ditches lie on the west side of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Virosidum]"}]'::jsonb),
    ('75dccc9d-fb68-40a9-aa2e-e58a47067580'::uuid, 'card_description', 'Cave temples hewn from solid basalt, mostly dedicated to Shiva, with sculptures blending Hindu and Buddhist iconography. The rock-cut reliefs date from the 2nd century BC.', 'Hewn from solid basalt on an island in Mumbai Harbour, the Elephanta Caves are temples chiefly for the god Shiva, their sculptures, mostly in high relief, blending Hindu and Buddhist ideas.', 'teaser-card-s008:75dccc9d-fb68-40a9-aa2e-e58a47067580:card_description', 'teaser-card-s008 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '7adbbcbaa17ccbb9f547121ce58572f71081b8a18fae40852e38a3affa6325bd|b0d42271ca99a1dd093c0c38a36c04463d153d6a1acc2a9695660c209a21c49f|b0d42271ca99a1dd093c0c38a36c04463d153d6a1acc2a9695660c209a21c49f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hewn from solid basalt on an island in Mumbai Harbour, the Elephanta Caves are temples chiefly for the god Shiva, their sculptures, mostly in high relief, blending Hindu and Buddhist ideas."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the caves are hewn from solid basalt [S5]; the caves are on an island in Mumbai Harbour [S2]; the caves are temples [S1]; the temples are chiefly dedicated to the god Shiva [S1]; the caves hold sculptures [S4]; the sculptures are mostly in high relief [S4]; the sculptures blend Hindu and Buddhist ideas [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Elephanta Caves are cave temples [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The temples are chiefly dedicated to the god Shiva [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The caves lie on an island (Elephanta Island) [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The island lies in Mumbai Harbour [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The caves are hewn from solid basalt [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The sculptures are mostly in high relief [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]; The sculptures blend Hindu and Buddhist ideas [SUPPORTED: https://en.wikipedia.org/wiki/Elephanta_Caves]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s008', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s008'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s008'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s008'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
